window.BAHR_DATA=window.BAHR_DATA||{};window.BAHR_DATA["passages-099"]=[{"id":"K099.01","q":"99:1–8","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · Heading and verses","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"Heading and verses [IV:783]","html":"<p>Medinan; also said to be Meccan. Eight verses. [The DKA heading additionally places its revelation after al-Nisāʾ.]\nIn the name of God, the All-Merciful, the Merciful.</p><p>When the earth is shaken with its shaking, (1) and the earth brings out its burdens, (2) and the human being says, “What is the matter with it?”—(3) on that day it will tell its tidings, (4) because your Lord has inspired it. (5) On that day people will come forth separately, to be shown their deeds. (6) Whoever does an atom’s weight of good will see it, (7) and whoever does an atom’s weight of evil will see it. (8)</p>","author":"kashshaf","source_id":"K099.01"}],"types":["exposition","language","theology","reports"],"ar":"مدنية وقيل مكية، وآياتها 8 [نزلت بعد النساء] بسم الله الرحمن الرحيم إذا زلزلت الأرض زلزالها (1) وأخرجت الأرض أثقالها (2) وقال الإنسان ما لها (3) يومئذ تحدث أخبارها (4) بأن ربك أوحى لها (5) يومئذ يصدر الناس أشتاتا ليروا أعمالهم (6) فمن يعمل مثقال ذرة خيرا يره (7) ومن يعمل مثقال ذرة شرا يره (8)","layers":[{"id":"K099.01","heading":"K099.01 — Heading and verses [IV:783]","text":"Medinan; also said to be Meccan. Eight verses. [The DKA heading additionally places its revelation after al-Nisāʾ.]\nIn the name of God, the All-Merciful, the Merciful.\n\nWhen the earth is shaken with its shaking, (1) and the earth brings out its burdens, (2) and the human being says, “What is the matter with it?”—(3) on that day it will tell its tidings, (4) because your Lord has inspired it. (5) On that day people will come forth separately, to be shown their deeds. (6) Whoever does an atom’s weight of good will see it, (7) and whoever does an atom’s weight of evil will see it. (8)","title":"Heading and verses [IV:783]","author":"kashshaf","surah":99,"ar":"مدنية وقيل مكية، وآياتها 8 [نزلت بعد النساء] بسم الله الرحمن الرحيم إذا زلزلت الأرض زلزالها (1) وأخرجت الأرض أثقالها (2) وقال الإنسان ما لها (3) يومئذ تحدث أخبارها (4) بأن ربك أوحى لها (5) يومئذ يصدر الناس أشتاتا ليروا أعمالهم (6) فمن يعمل مثقال ذرة خيرا يره (7) ومن يعمل مثقال ذرة شرا يره (8)","html":"<p>Medinan; also said to be Meccan. Eight verses. [The DKA heading additionally places its revelation after al-Nisāʾ.]\nIn the name of God, the All-Merciful, the Merciful.</p><p>When the earth is shaken with its shaking, (1) and the earth brings out its burdens, (2) and the human being says, “What is the matter with it?”—(3) on that day it will tell its tidings, (4) because your Lord has inspired it. (5) On that day people will come forth separately, to be shown their deeds. (6) Whoever does an atom’s weight of good will see it, (7) and whoever does an atom’s weight of evil will see it. (8)</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:1","number":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","en":"When Earth is shaken with her (final) earthquake"},{"key":"99:2","number":2,"ar":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","en":"And Earth yieldeth up her burdens"},{"key":"99:3","number":3,"ar":"وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا","en":"And man saith: What aileth her"},{"key":"99:4","number":4,"ar":"يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا","en":"That day she will relate her chronicles"},{"key":"99:5","number":5,"ar":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","en":"Because thy Lord inspireth her"},{"key":"99:6","number":6,"ar":"يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ","en":"That day mankind will issue forth in scattered groups to be shown their deeds"},{"key":"99:7","number":7,"ar":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ","en":"And whoso doeth good an atom's weight will see it then"},{"key":"99:8","number":8,"ar":"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ","en":"And whoso doeth ill an atom's weight will see it then"}],"quran_ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا ﴿1﴾ وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا ﴿2﴾ وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا ﴿3﴾ يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿4﴾ بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا ﴿5﴾ يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ ﴿6﴾ فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ ﴿7﴾ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ ﴿8﴾","quran_en":"1. When Earth is shaken with her (final) earthquake 2. And Earth yieldeth up her burdens 3. And man saith: What aileth her 4. That day she will relate her chronicles 5. Because thy Lord inspireth her 6. That day mankind will issue forth in scattered groups to be shown their deeds 7. And whoso doeth good an atom's weight will see it then 8. And whoso doeth ill an atom's weight will see it then"},{"id":"K099.02","q":"99:1–2","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · The shaking and the burdens","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"The shaking and the burdens [IV:783]","html":"<p>Zilzālahā is read with kasra (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كَسْرة</bdi>) or fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>) on the zāy (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ز</bdi>). With kasra (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كَسْرة</bdi>) it is a verbal noun; with fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>), a noun. Among word-patterns, faʿlāl (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَعْلال</bdi>) with fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>) occurs only in a reduplicated form.</p><p>If you ask what “its shaking” means in the possessive construction, I answer: the shaking that befits it in accordance with wisdom and God’s will—the violent shaking beyond which there is none. Compare: “Honour the pious man with his honour, and abase the impious man with his abasement,” meaning the honour and abasement they respectively deserve. Or it means its entire shaking, every degree of shaking possible for it.</p><p>Athqāl is the plural of thaqal (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ثَقَل</bdi>), household goods, as in “They carry your burdens” [16:7]. He makes the things buried within the earth its burdens.</p>","author":"kashshaf","source_id":"K099.02"},{"type":"exposition","title":"The word-pattern faʿlāl [XVI:536]","html":"<p>Medinan; nine verses. In the name of God, the All-Merciful, the Merciful. [The embedded Kashshāf heading instead records disagreement about the place of revelation; both headings here give nine verses.]</p><p>On “among word-patterns, faʿlāl (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَعْلال</bdi>) with fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>) occurs only in a reduplicated form,” al-Kawāshī has: “The expression nāqa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ناقة</bdi>) <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">جزعال</bdi> occurs, meaning a she-camel which [probably ‘limps’; the electronic text reads <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تطلع</bdi>, ‘looks out/climbs’], as does qasṭāl (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">قَسْطال</bdi>), a word for dust; neither is reduplicated. It is said that Bahrām and Shahrām are foreign.” As for qahqār (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">قَهْقار</bdi>), it is a weak linguistic form. Al-Ṣiḥāḥ has: “Qahqarr, with doubled rāʾ (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ر</bdi>), is hard stone. Aḥmad ibn Yaḥyā alone used to say qahqār (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">قَهْقار</bdi>).”</p>","author":"tibi","source_id":"T099.01"},{"type":"exposition","title":"A shaking beyond which there is none [XVI:537]","html":"<p>On “beyond which there is none”: no shaking comes beyond it—that is, none surpasses it or is stronger. Al-Mughrib says: “The expression wa-in kāna laysa bi-lladhī lā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">لا</bdi>) baʿda (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بعد</bdi>) lahu means ‘although it is not the ultimate in excellence.’ It derives from their saying, ‘This is something beyond which there is no further extreme of excellence or badness.’ Sometimes they abbreviate it and say laysa baʿdahu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بعده</bdi>), ‘there is none beyond it’; then the lā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">لا</bdi>) that negates an entire class is introduced, and [baʿd (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بعد</bdi>)] is used like a fully declinable noun.”</p><p>On “or its entire shaking”: the measure appropriate to it and attributed to it. The difference from the preceding interpretation is that the first refers to the agent and the requirement of His will. Hence he says, “the shaking that befits it in accordance with wisdom.” The second, although indicating comprehensiveness, is less intense than the first. His phrase “befits it in accordance with wisdom” alludes to his doctrinal position.</p><p>The Imām says: “That is, the shaking prescribed for it, if it is conceived as a living being. It is related that it shakes from the intensity of Isrāfīl’s voice.” This works only if it is conceived as alive and frightened, just as it is made speaking in “it tells its tidings.”</p><p>On “He makes the things buried within it its burdens,” al-Rāghib says: “Its burdens are said to be its treasures, or the human bodies it contains at the resurrection. ‘They carry your burdens’ [16:7] means your heavy loads.”</p>","author":"tibi","source_id":"T099.02"}],"types":["exposition","language","theology","reports"],"ar":"زلزالها قرئ بكسر الزاى وفتحها، فالمكسور مصدر، والمفتوح: اسم، وليس في الأبنية فعلال بالفتح إلا في المضاعف. فإن قلت: ما معنى زلزالها بالإضافة؟ قلت: معناه زلزالها الذي تستوجبه في الحكمة ومشيئة الله، وهو الزلزال الشديد الذي ليس بعده. ونحوه قولك: أكرم التقى إكرامه، وأهن الفاسق إهانته، تريد: ما يستوجبانه من الإكرام والإهانة أو زلزالها كله وجميع ما هو ممكن منه. الأثقال: جمع ثقل. وهو متاع البيت، وتحمل أثقالكم جعل ما في جوفها من الدفائن أثقالا لها\n\nمدنية، وهي تسع آيات\n\nبسم الله الرحمن الرحيم\n\nقوله: (وليس في الأبنية فعلال بالفتح إلا في المضاعف)، وفي \"الكواشي\": \"وقد جاء \"ناقة جزعال\" التي تطلع، و\"قصطال\" اسم للغبار، وليسا من المضاعف. وقيل: أما بهرام وشهرام فعجميان\". وأما القهقار فلغة ضعيفة؛ في \"الصحاح\": \"القهقر، بتشديد الراء: الحجر الصلب، وكان أحمد بن يحيى وحده يقول: القهقار\".\n\nقوله: (الذي ليس بعده)، أي: ليس بعده زلزال، أي: ليس فوقه وأقوى منه.\n\nالمغرب: \"وقوله: وإن كان ليس بالذي لا بعد له، أي: ليس بنهاية في الجودة وهو من قولهم: هذا مما ليس بعده غاية في الجودة والرداءة. وربما اختصروا وقالوا: ليس بعده، ثم أُدخل عليه \"لا\" النافية للجنس، واستعمل استعمال الاسم المتمكن\".\n\nقوله: (أو زلزالها كله)، أي: القدر اللائق بها ويضاف إليها. والفرق بينه وبين الوجه السابق، هو أن السابق مستند إلى الفاعل ومقتضٍ مشيئته، ومن ثم قال: \"زلزالها الذي تستوجبه في الحكمة\". والثاني وإن دل على الشمول، ولكن دون الأول في الشدة، وفي قوله \"تستوجبه في الحكمة\" إشارة إلى مذهبه، قال الإمام: \"أي الزلزال المكتوب عليها إذا قُدرت تقدير الحي. روي أنها تُزلزل من شدة صوت إسرافيل عليه السلام\"، وليس ذلك إلا إذا قُدر أنها حية فزعة، كما كانت متكلمة في قوله: ﴿تُحَدِّثُ أَخْبَارَهَا﴾.\n\nقوله: (جعل ما في جوفها من الدفائن أثقالاً لها)، الراغب: \"أثقالها: قيل: كنوزها، وقيل: ما تضمنت من أجساد البشر عند الحشر، وقوله: ﴿وَتَحْمِلُ أَثْقَالَكُمْ﴾ [النحل: 7]: أي: أحمالكم الثقيلة\".","layers":[{"id":"K099.02","heading":"K099.02 — The shaking and the burdens [IV:783]","text":"Zilzālahā is read with kasra (كَسْرة) or fatḥa (فَتْحة) on the zāy (ز). With kasra (كَسْرة) it is a verbal noun; with fatḥa (فَتْحة), a noun. Among word-patterns, faʿlāl (فَعْلال) with fatḥa (فَتْحة) occurs only in a reduplicated form.\n\nIf you ask what “its shaking” means in the possessive construction, I answer: the shaking that befits it in accordance with wisdom and God’s will—the violent shaking beyond which there is none. Compare: “Honour the pious man with his honour, and abase the impious man with his abasement,” meaning the honour and abasement they respectively deserve. Or it means its entire shaking, every degree of shaking possible for it.\n\nAthqāl is the plural of thaqal (ثَقَل), household goods, as in “They carry your burdens” [16:7]. He makes the things buried within the earth its burdens.","title":"The shaking and the burdens [IV:783]","author":"kashshaf","surah":99,"ar":"زلزالها قرئ بكسر الزاى وفتحها، فالمكسور مصدر، والمفتوح: اسم، وليس في الأبنية فعلال بالفتح إلا في المضاعف. فإن قلت: ما معنى زلزالها بالإضافة؟ قلت: معناه زلزالها الذي تستوجبه في الحكمة ومشيئة الله، وهو الزلزال الشديد الذي ليس بعده. ونحوه قولك: أكرم التقى إكرامه، وأهن الفاسق إهانته، تريد: ما يستوجبانه من الإكرام والإهانة أو زلزالها كله وجميع ما هو ممكن منه. الأثقال: جمع ثقل. وهو متاع البيت، وتحمل أثقالكم جعل ما في جوفها من الدفائن أثقالا لها","html":"<p>Zilzālahā is read with kasra (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كَسْرة</bdi>) or fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>) on the zāy (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ز</bdi>). With kasra (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كَسْرة</bdi>) it is a verbal noun; with fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>), a noun. Among word-patterns, faʿlāl (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَعْلال</bdi>) with fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>) occurs only in a reduplicated form.</p><p>If you ask what “its shaking” means in the possessive construction, I answer: the shaking that befits it in accordance with wisdom and God’s will—the violent shaking beyond which there is none. Compare: “Honour the pious man with his honour, and abase the impious man with his abasement,” meaning the honour and abasement they respectively deserve. Or it means its entire shaking, every degree of shaking possible for it.</p><p>Athqāl is the plural of thaqal (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ثَقَل</bdi>), household goods, as in “They carry your burdens” [16:7]. He makes the things buried within the earth its burdens.</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.01","heading":"T099.01 — The word-pattern faʿlāl [XVI:536]","text":"Medinan; nine verses. In the name of God, the All-Merciful, the Merciful. [The embedded Kashshāf heading instead records disagreement about the place of revelation; both headings here give nine verses.]\n\nOn “among word-patterns, faʿlāl (فَعْلال) with fatḥa (فَتْحة) occurs only in a reduplicated form,” al-Kawāshī has: “The expression nāqa (ناقة) جزعال occurs, meaning a she-camel which [probably ‘limps’; the electronic text reads تطلع, ‘looks out/climbs’], as does qasṭāl (قَسْطال), a word for dust; neither is reduplicated. It is said that Bahrām and Shahrām are foreign.” As for qahqār (قَهْقار), it is a weak linguistic form. Al-Ṣiḥāḥ has: “Qahqarr, with doubled rāʾ (ر), is hard stone. Aḥmad ibn Yaḥyā alone used to say qahqār (قَهْقار).”","title":"The word-pattern faʿlāl [XVI:536]","author":"tibi","on":["K099.02"],"anchor":"K099.02","surah":99,"ar":"مدنية، وهي تسع آيات\n\nبسم الله الرحمن الرحيم\n\nقوله: (وليس في الأبنية فعلال بالفتح إلا في المضاعف)، وفي \"الكواشي\": \"وقد جاء \"ناقة جزعال\" التي تطلع، و\"قصطال\" اسم للغبار، وليسا من المضاعف. وقيل: أما بهرام وشهرام فعجميان\". وأما القهقار فلغة ضعيفة؛ في \"الصحاح\": \"القهقر، بتشديد الراء: الحجر الصلب، وكان أحمد بن يحيى وحده يقول: القهقار\".","html":"<p>Medinan; nine verses. In the name of God, the All-Merciful, the Merciful. [The embedded Kashshāf heading instead records disagreement about the place of revelation; both headings here give nine verses.]</p><p>On “among word-patterns, faʿlāl (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَعْلال</bdi>) with fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>) occurs only in a reduplicated form,” al-Kawāshī has: “The expression nāqa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ناقة</bdi>) <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">جزعال</bdi> occurs, meaning a she-camel which [probably ‘limps’; the electronic text reads <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تطلع</bdi>, ‘looks out/climbs’], as does qasṭāl (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">قَسْطال</bdi>), a word for dust; neither is reduplicated. It is said that Bahrām and Shahrām are foreign.” As for qahqār (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">قَهْقار</bdi>), it is a weak linguistic form. Al-Ṣiḥāḥ has: “Qahqarr, with doubled rāʾ (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ر</bdi>), is hard stone. Aḥmad ibn Yaḥyā alone used to say qahqār (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">قَهْقار</bdi>).”</p>","lemma":"وليس في الأبنية فعلال بالفتح إلا في المضاعف","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.02","heading":"T099.02 — A shaking beyond which there is none [XVI:537]","text":"On “beyond which there is none”: no shaking comes beyond it—that is, none surpasses it or is stronger. Al-Mughrib says: “The expression wa-in kāna laysa bi-lladhī lā (لا) baʿda (بعد) lahu means ‘although it is not the ultimate in excellence.’ It derives from their saying, ‘This is something beyond which there is no further extreme of excellence or badness.’ Sometimes they abbreviate it and say laysa baʿdahu (بعده), ‘there is none beyond it’; then the lā (لا) that negates an entire class is introduced, and [baʿd (بعد)] is used like a fully declinable noun.”\n\nOn “or its entire shaking”: the measure appropriate to it and attributed to it. The difference from the preceding interpretation is that the first refers to the agent and the requirement of His will. Hence he says, “the shaking that befits it in accordance with wisdom.” The second, although indicating comprehensiveness, is less intense than the first. His phrase “befits it in accordance with wisdom” alludes to his doctrinal position.\n\nThe Imām says: “That is, the shaking prescribed for it, if it is conceived as a living being. It is related that it shakes from the intensity of Isrāfīl’s voice.” This works only if it is conceived as alive and frightened, just as it is made speaking in “it tells its tidings.”\n\nOn “He makes the things buried within it its burdens,” al-Rāghib says: “Its burdens are said to be its treasures, or the human bodies it contains at the resurrection. ‘They carry your burdens’ [16:7] means your heavy loads.”","title":"A shaking beyond which there is none [XVI:537]","author":"tibi","on":["K099.02"],"anchor":"K099.02","surah":99,"ar":"قوله: (الذي ليس بعده)، أي: ليس بعده زلزال، أي: ليس فوقه وأقوى منه.\n\nالمغرب: \"وقوله: وإن كان ليس بالذي لا بعد له، أي: ليس بنهاية في الجودة وهو من قولهم: هذا مما ليس بعده غاية في الجودة والرداءة. وربما اختصروا وقالوا: ليس بعده، ثم أُدخل عليه \"لا\" النافية للجنس، واستعمل استعمال الاسم المتمكن\".\n\nقوله: (أو زلزالها كله)، أي: القدر اللائق بها ويضاف إليها. والفرق بينه وبين الوجه السابق، هو أن السابق مستند إلى الفاعل ومقتضٍ مشيئته، ومن ثم قال: \"زلزالها الذي تستوجبه في الحكمة\". والثاني وإن دل على الشمول، ولكن دون الأول في الشدة، وفي قوله \"تستوجبه في الحكمة\" إشارة إلى مذهبه، قال الإمام: \"أي الزلزال المكتوب عليها إذا قُدرت تقدير الحي. روي أنها تُزلزل من شدة صوت إسرافيل عليه السلام\"، وليس ذلك إلا إذا قُدر أنها حية فزعة، كما كانت متكلمة في قوله: ﴿تُحَدِّثُ أَخْبَارَهَا﴾.\n\nقوله: (جعل ما في جوفها من الدفائن أثقالاً لها)، الراغب: \"أثقالها: قيل: كنوزها، وقيل: ما تضمنت من أجساد البشر عند الحشر، وقوله: ﴿وَتَحْمِلُ أَثْقَالَكُمْ﴾ [النحل: 7]: أي: أحمالكم الثقيلة\".","html":"<p>On “beyond which there is none”: no shaking comes beyond it—that is, none surpasses it or is stronger. Al-Mughrib says: “The expression wa-in kāna laysa bi-lladhī lā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">لا</bdi>) baʿda (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بعد</bdi>) lahu means ‘although it is not the ultimate in excellence.’ It derives from their saying, ‘This is something beyond which there is no further extreme of excellence or badness.’ Sometimes they abbreviate it and say laysa baʿdahu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بعده</bdi>), ‘there is none beyond it’; then the lā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">لا</bdi>) that negates an entire class is introduced, and [baʿd (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بعد</bdi>)] is used like a fully declinable noun.”</p><p>On “or its entire shaking”: the measure appropriate to it and attributed to it. The difference from the preceding interpretation is that the first refers to the agent and the requirement of His will. Hence he says, “the shaking that befits it in accordance with wisdom.” The second, although indicating comprehensiveness, is less intense than the first. His phrase “befits it in accordance with wisdom” alludes to his doctrinal position.</p><p>The Imām says: “That is, the shaking prescribed for it, if it is conceived as a living being. It is related that it shakes from the intensity of Isrāfīl’s voice.” This works only if it is conceived as alive and frightened, just as it is made speaking in “it tells its tidings.”</p><p>On “He makes the things buried within it its burdens,” al-Rāghib says: “Its burdens are said to be its treasures, or the human bodies it contains at the resurrection. ‘They carry your burdens’ [16:7] means your heavy loads.”</p>","lemma":"الذي ليس بعده","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:1","number":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","en":"When Earth is shaken with her (final) earthquake"},{"key":"99:2","number":2,"ar":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","en":"And Earth yieldeth up her burdens"}],"quran_ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا ﴿1﴾ وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا ﴿2﴾","quran_en":"1. When Earth is shaken with her (final) earthquake 2. And Earth yieldeth up her burdens"},{"id":"K099.03","q":"99:3–4","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · The human being’s question and the earth’s speech","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"The human being’s question and the earth’s speech [IV:783–784]","html":"<p>“And the human being says, ‘What is the matter with it?’”—that it has shaken so violently and cast out what was in its belly. This occurs at the second blast, when it shakes and casts out its dead alive. They say this because of the dreadful event that overwhelms them, just as they say, “Who has raised us from our sleeping-place?” [36:52]. It is also said that this is the unbeliever’s speech, because he did not believe in resurrection; the believer says, “This is what the All-Merciful promised, and the messengers spoke truly” [36:52].</p><p>If you ask what the earth’s telling and its being inspired mean, I answer: this is figurative language for God’s bringing about in it states that take the place of telling by the tongue. Someone who asks, “What is the matter with it?”, looks at those states and knows why it shook and why it cast out the dead, and that this is what the prophets used to forewarn of and caution against.</p><p>It is also said that God literally makes it speak and it reports the good and evil done upon it. It is related from God’s Messenger: “It bears witness against everyone concerning what he did upon its surface.”</p>","author":"kashshaf","source_id":"K099.03"},{"type":"exposition","title":"The implied circumstance and the earth’s testimony [XVI:538]","html":"<p>On “‘What is the matter with it?’—that it has shaken”: it is said that this indicates an omission in the expression. The omitted clause is circumstantial, referring to the pronoun governed by the preposition, because it functions as an object: what has happened to it in this state? Compare His saying, “What is the matter with them, turning away from the reminder?” [74:49].</p><p>On “it bears witness against everyone concerning what he did upon its surface”: Imām Aḥmad ibn Ḥanbal and al-Tirmidhī transmit from Abū Hurayra that God’s Messenger recited “On that day it will tell its tidings” and asked, “Do you know what its tidings are?” They said, “God and His Messenger know best.” He said: “Its tidings are that it bears witness against every male or female servant concerning what they did on its surface. It says, ‘On such-and-such a day, he did such-and-such.’ These are its tidings.”</p>","author":"tibi","source_id":"T099.03"}],"types":["exposition","language","theology","reports"],"ar":"وقال الإنسان ما لها زلزلت هذه الزلزلة الشديدة ولفظت ما في بطنها، وذلك عند النفخة الثانية حين تزلزل وتلفظ أمواتها أحياء، فيقولون ذلك لما يبهرهم من الأمر الفظيع، كما يقولون: من بعثنا من مرقدنا. وقيل: هذا قول الكافر، لأنه كان لا يؤمن بالبعث، فأما المؤمن فيقول: هذا ما وعد الرحمن وصدق المرسلون. فإن قلت: ما معنى تحديث الأرض والإيحاء لها؟ قلت: هو مجاز عن إحداث الله تعالى فيها من الأحوال ما يقوم مقام التحديث باللسان، حتى ينظر من يقول مالها إلى تلك الأحوال، فيعلم لم زلزلت ولم لفظت الأموات؟ وأن هذا ما كانت الأنبياء ينذرونه ويحذرون منه. وقيل: ينطقها الله على الحقيقة. وتخبر بما عمل عليها من خير وشر. وروى عن رسول الله صلى الله عليه وسلم تشهد على كل أحد بما عمل على ظهرها .\n\nقوله: (﴿مَا لَهَا﴾ زُلزلت؟ )، قيل: هذه إشارة إلى أن في الكلام حذفاً، وهو حال من الضمير المجرور لأنه مفعول، أي: أي شيء ثبت لها في هذه الحال، لقوله تعالى: ﴿فَمَا لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ﴾ [المدثر: 49].\n\nقوله: (تشهد على كل أحد بما عمل على ظهرها)، روى الإمام أحمد بن حنبل والترمذي، عن أبي هريرة، قال: قرأ رسول الله ﷺ هذه الآية: ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾، قال: \"أتدرون ما أخبارها؟ \" قالوا: الله ورسوله أعلم. قال: \"فإن أخبارها أن تشهد على كل عبد أو أمة بما عمل على ظهرها، تقول: عمل يوم [كذا] كذا وكذا، فهذه أخبارها\".","layers":[{"id":"K099.03","heading":"K099.03 — The human being’s question and the earth’s speech [IV:783–784]","text":"“And the human being says, ‘What is the matter with it?’”—that it has shaken so violently and cast out what was in its belly. This occurs at the second blast, when it shakes and casts out its dead alive. They say this because of the dreadful event that overwhelms them, just as they say, “Who has raised us from our sleeping-place?” [36:52]. It is also said that this is the unbeliever’s speech, because he did not believe in resurrection; the believer says, “This is what the All-Merciful promised, and the messengers spoke truly” [36:52].\n\nIf you ask what the earth’s telling and its being inspired mean, I answer: this is figurative language for God’s bringing about in it states that take the place of telling by the tongue. Someone who asks, “What is the matter with it?”, looks at those states and knows why it shook and why it cast out the dead, and that this is what the prophets used to forewarn of and caution against.\n\nIt is also said that God literally makes it speak and it reports the good and evil done upon it. It is related from God’s Messenger: “It bears witness against everyone concerning what he did upon its surface.”","title":"The human being’s question and the earth’s speech [IV:783–784]","author":"kashshaf","surah":99,"ar":"وقال الإنسان ما لها زلزلت هذه الزلزلة الشديدة ولفظت ما في بطنها، وذلك عند النفخة الثانية حين تزلزل وتلفظ أمواتها أحياء، فيقولون ذلك لما يبهرهم من الأمر الفظيع، كما يقولون: من بعثنا من مرقدنا. وقيل: هذا قول الكافر، لأنه كان لا يؤمن بالبعث، فأما المؤمن فيقول: هذا ما وعد الرحمن وصدق المرسلون. فإن قلت: ما معنى تحديث الأرض والإيحاء لها؟ قلت: هو مجاز عن إحداث الله تعالى فيها من الأحوال ما يقوم مقام التحديث باللسان، حتى ينظر من يقول مالها إلى تلك الأحوال، فيعلم لم زلزلت ولم لفظت الأموات؟ وأن هذا ما كانت الأنبياء ينذرونه ويحذرون منه. وقيل: ينطقها الله على الحقيقة. وتخبر بما عمل عليها من خير وشر. وروى عن رسول الله صلى الله عليه وسلم تشهد على كل أحد بما عمل على ظهرها .","html":"<p>“And the human being says, ‘What is the matter with it?’”—that it has shaken so violently and cast out what was in its belly. This occurs at the second blast, when it shakes and casts out its dead alive. They say this because of the dreadful event that overwhelms them, just as they say, “Who has raised us from our sleeping-place?” [36:52]. It is also said that this is the unbeliever’s speech, because he did not believe in resurrection; the believer says, “This is what the All-Merciful promised, and the messengers spoke truly” [36:52].</p><p>If you ask what the earth’s telling and its being inspired mean, I answer: this is figurative language for God’s bringing about in it states that take the place of telling by the tongue. Someone who asks, “What is the matter with it?”, looks at those states and knows why it shook and why it cast out the dead, and that this is what the prophets used to forewarn of and caution against.</p><p>It is also said that God literally makes it speak and it reports the good and evil done upon it. It is related from God’s Messenger: “It bears witness against everyone concerning what he did upon its surface.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.03","heading":"T099.03 — The implied circumstance and the earth’s testimony [XVI:538]","text":"On “‘What is the matter with it?’—that it has shaken”: it is said that this indicates an omission in the expression. The omitted clause is circumstantial, referring to the pronoun governed by the preposition, because it functions as an object: what has happened to it in this state? Compare His saying, “What is the matter with them, turning away from the reminder?” [74:49].\n\nOn “it bears witness against everyone concerning what he did upon its surface”: Imām Aḥmad ibn Ḥanbal and al-Tirmidhī transmit from Abū Hurayra that God’s Messenger recited “On that day it will tell its tidings” and asked, “Do you know what its tidings are?” They said, “God and His Messenger know best.” He said: “Its tidings are that it bears witness against every male or female servant concerning what they did on its surface. It says, ‘On such-and-such a day, he did such-and-such.’ These are its tidings.”","title":"The implied circumstance and the earth’s testimony [XVI:538]","author":"tibi","on":["K099.03"],"anchor":"K099.03","surah":99,"ar":"قوله: (﴿مَا لَهَا﴾ زُلزلت؟ )، قيل: هذه إشارة إلى أن في الكلام حذفاً، وهو حال من الضمير المجرور لأنه مفعول، أي: أي شيء ثبت لها في هذه الحال، لقوله تعالى: ﴿فَمَا لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ﴾ [المدثر: 49].\n\nقوله: (تشهد على كل أحد بما عمل على ظهرها)، روى الإمام أحمد بن حنبل والترمذي، عن أبي هريرة، قال: قرأ رسول الله ﷺ هذه الآية: ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾، قال: \"أتدرون ما أخبارها؟ \" قالوا: الله ورسوله أعلم. قال: \"فإن أخبارها أن تشهد على كل عبد أو أمة بما عمل على ظهرها، تقول: عمل يوم [كذا] كذا وكذا، فهذه أخبارها\".","html":"<p>On “‘What is the matter with it?’—that it has shaken”: it is said that this indicates an omission in the expression. The omitted clause is circumstantial, referring to the pronoun governed by the preposition, because it functions as an object: what has happened to it in this state? Compare His saying, “What is the matter with them, turning away from the reminder?” [74:49].</p><p>On “it bears witness against everyone concerning what he did upon its surface”: Imām Aḥmad ibn Ḥanbal and al-Tirmidhī transmit from Abū Hurayra that God’s Messenger recited “On that day it will tell its tidings” and asked, “Do you know what its tidings are?” They said, “God and His Messenger know best.” He said: “Its tidings are that it bears witness against every male or female servant concerning what they did on its surface. It says, ‘On such-and-such a day, he did such-and-such.’ These are its tidings.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:3","number":3,"ar":"وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا","en":"And man saith: What aileth her"},{"key":"99:4","number":4,"ar":"يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا","en":"That day she will relate her chronicles"}],"quran_ar":"وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا ﴿3﴾ يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿4﴾","quran_en":"3. And man saith: What aileth her 4. That day she will relate her chronicles"},{"id":"K099.04","q":"99:1–4","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · Adverbials and the objects of “tell”","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"Adverbials and the objects of “tell” [IV:784]","html":"<p>If you ask what governs the accusative of idhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">إذا</bdi>), “when,” and yawmaʾidhin (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">يومئذ</bdi>), “on that day,” I answer: yawmaʾidhin (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">يومئذ</bdi>) substitutes for idhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">إذا</bdi>), and tuḥaddithu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تحدّث</bdi>), “it tells,” governs both. Alternatively, idhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">إذا</bdi>) may be governed by an omitted verb, and yawmaʾidhin (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">يومئذ</bdi>) by tuḥaddithu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تحدّث</bdi>).</p><p>If you ask where the two objects of tuḥaddithu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تحدّث</bdi>) are, I answer: the first is omitted and the second is “its tidings.” The underlying expression is “it tells created beings its tidings.” But the aim is to mention its telling the tidings, not to mention created beings, in order to magnify the day.</p>","author":"kashshaf","source_id":"K099.04"},{"type":"exposition","title":"Does “tell” take one object, two, or three? [XVI:539–540]","html":"<p>On “where are the two objects of ‘it tells’?”: it is said that both question and answer are open to examination. Ḥaddatha does not take two objects; it takes one. The omitted term explicitly supplied here is the direct object; the expressed term, “its tidings,” is an absolute object, a verbal-noun complement. These are not called “two objects” in the grammarians’ technical usage.</p><p>True, when the particular content of the verbal noun is mentioned in this construction, it is made accusative. Some grammarians then call its components a second and third object, as in “I told Zayd that ʿAmr was standing,” and call the verb transitive to three objects. It has been stated and established in its proper place that this is not so: the verb takes one object, while “Zayd standing” is accusative because it occupies the place of the verbal noun. But when the verbal noun is explicitly expressed, as in “I told him a telling and a report,” no one says that the verb takes two objects.</p><p>The proof is that, after explaining that “Zayd standing” is accusative in such a construction because it occupies the place of a verbal noun, rather than being a second and third object, Ibn al-Ḥājib says: “It remains to ask how something that is not an action in meaning—the supposed second and third objects—can occupy the position of a verbal noun.” He answers: “It was not a verbal noun insofar as it was ‘Zayd standing,’ but insofar as it was a particular report. The aspect that permits it to be predicated of ‘the report’ when you say, ‘Zayd told me that ʿAmr was departing,’ is the same aspect that permits it to occupy the place of a verbal noun.”</p><p>I say: one may answer that ḥaddatha (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">حدّث</bdi>) and its sister verbs truly take one object, and that making them take three or two involves figurative extension or incorporation of another verb’s meaning. Al-Mufaṣṣal says: “Ḥaddathtu is treated like aʿlamtu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أعلمت</bdi>), ‘I informed,’ because it agrees with it in meaning, and is therefore made transitive in the same way.” The author of al-Iqlīd says: “Anbaʾa, nabbaʾa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">نبّأ</bdi>), akhbara, and khabbara originally take one object: anbaʾtu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أنبأت</bdi>) Zaydan bi-kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بكذا</bdi>), ‘I informed Zayd of such-and-such.’ The preposition is then omitted and one says anbaʾtuhu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أنبأته</bdi>) kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كذا</bdi>). In revelation, ‘Who informed you of this?’ [66:3] means bi-hādhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بهذا</bdi>), ‘of this’; and ‘Inform My servants that I am the Forgiving, the Merciful’ [15:49]. When these verbs take three objects, this is only because they are treated like aʿlamtu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أعلمت</bdi>).”</p><p>It is therefore clear that the author’s question rests on this analysis. His answer indicates it when he explicitly says: “As though it were said, ‘On that day it tells its tidings: that your Lord has inspired it,’ because one says both ‘I told him such-and-such’ and ‘I told him of such-and-such.’”</p>","author":"tibi","source_id":"T099.04"},{"type":"exposition","title":"Why the hearers are omitted [XVI:540]","html":"<p>On “the aim is to mention its telling the tidings”: the purpose in the verse is the second object, not the first, because the sūrah is directed toward the terror of the Resurrection. That is: a tremendous day on which inanimate things speak.</p>","author":"tibi","source_id":"T099.05"}],"types":["exposition","language","theology","reports"],"ar":"فإن قلت: إذا، ويومئذ: ما ناصبهما؟ قلت: يومئذ: بدل من إذا، وناصبهما تحدث. ويجوز أن ينتصب إذا بمضمر، ويومئذ بتحدث. فإن قلت: أين مفعولا تحدث؟ قلت: قد حذف أولهما، والثاني أخبارها، وأصله تحدث الخلق أخبارها، إلا أن المقصود ذكر تحديثها الأخبار لا ذكر الخلق تعظيما لليوم.\n\nقوله: (أين مفعولا ﴿تُحَدِّثُ﴾؟ )، قيل: في السؤال والجواب نظر، لأن \"حدث\" ليس متعدياً إلى مفعولين، بل هو متعد إلى مفعول واحد، والمحذوف الذي صرح بذكره هاهنا هو المفعول به، وأما المذكور وهو ﴿أَخْبَارَهَا﴾ فمفعول مطلق، وهما لا يُسميان مفعولين في اصطلاح النحاة.\n\nنعم، إذا ذُكرت خصوصية المصدر في هذا الباب جُعل منصوباً، ويسميه بعض النحاة حينئذ مفعولاً ثانياً وثالثاً، نحو: حدثت زيداً عمراً قائماً، ويقال حينئذ: هو متعد إلى ثلاثة مفاعيل، وقد ذُكر وحُقق في موضعه أنه ليس كذلك، وأنه متعد إلى واحد، وأن \"زيداً قائماً\" نصبا لوقوعهما موقع المصدر. وأما إذا ذُكر المصدر بلفظه نحو: حدثته حديثاً وخبراً، فلا يقول أحد/ إنه متعد إلى مفعولين.\n\nوالدليل على ما ذكرنا أن ابن الحاجب بعدما بين أن \"زيداً قائماً\" نُصب في مثل هذا الموضع لوقوعه موقع المصدر، لا لكونه مفعولاً ثانياً وثالثاً، قال: \"بقى أن يقال: كيف يصح أن يقع ما ليس بفعل في المعنى مصدراً، وهو المفعول الثاني والثالث؟ \" ثم قال: \"والجواب عنه أنه لم يكن مصدراً باعتبار كونه زيداً قائماً، ولكن باعتبار كونه حديثاً مخصوصاً، فالوجه الذي صح الإخبار به عن الحديث إذا قلت: حدثني زيد عمرو منطلق، هو الذي صحح وقوعه مصدراً\".\n\nوقلت: ويمكن أن يقال: إن \"حدثت وأخواتها\" متعديات إلى مفعول واحد حقيقة، وجعلها متعديات إلى ثلاثة أو إلى اثنين تجوز أو تضمين؛ قال في \"المفصل\": \"حدثت\n\nأُجري مجرى أعلمت لموافقته له في معناه، فعُدي بتعديه\". قال صاحب \"الإقليد\": \"الأصل في أنبأ ونبأ، وأخبر وخبر، التعدي إلى مفعول واحد، نحو: أنبأت زيداً بكذا، ثم حُذف الجار فيقال: أنبأته كذا، وفي التنزيل: ﴿مَنْ أَنبَأَكَ هَذَا﴾ [التحريم: 3]، أي: بهذا، ﴿نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ﴾ [الحجر: 49]؛ فإذا عُديت إلى ثلاثة، فليس إلا لإجرائها مجرى أعلمت\".\n\nفظهر أن سؤال المصنف مبني على هذا، وجوابه يدل عليه حيث صرح بقوله: \"كأنه قيل: يومئذ تحدث أخبارها، بأن ربك أوحى لها؛ لأنك تقول: حدثته كذا وحدثته بكذا\".\n\nقوله: (إلا أن المقصود ذكر تحديثها الأخبار)، أي: الغرض في الآية هو المفعول الثاني لا الأول، لأن السورة مسوقة في هول القيامة، أي: يوم عظيم تحدث فيه الجمادات.","layers":[{"id":"K099.04","heading":"K099.04 — Adverbials and the objects of “tell” [IV:784]","text":"If you ask what governs the accusative of idhā (إذا), “when,” and yawmaʾidhin (يومئذ), “on that day,” I answer: yawmaʾidhin (يومئذ) substitutes for idhā (إذا), and tuḥaddithu (تحدّث), “it tells,” governs both. Alternatively, idhā (إذا) may be governed by an omitted verb, and yawmaʾidhin (يومئذ) by tuḥaddithu (تحدّث).\n\nIf you ask where the two objects of tuḥaddithu (تحدّث) are, I answer: the first is omitted and the second is “its tidings.” The underlying expression is “it tells created beings its tidings.” But the aim is to mention its telling the tidings, not to mention created beings, in order to magnify the day.","title":"Adverbials and the objects of “tell” [IV:784]","author":"kashshaf","surah":99,"ar":"فإن قلت: إذا، ويومئذ: ما ناصبهما؟ قلت: يومئذ: بدل من إذا، وناصبهما تحدث. ويجوز أن ينتصب إذا بمضمر، ويومئذ بتحدث. فإن قلت: أين مفعولا تحدث؟ قلت: قد حذف أولهما، والثاني أخبارها، وأصله تحدث الخلق أخبارها، إلا أن المقصود ذكر تحديثها الأخبار لا ذكر الخلق تعظيما لليوم.","html":"<p>If you ask what governs the accusative of idhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">إذا</bdi>), “when,” and yawmaʾidhin (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">يومئذ</bdi>), “on that day,” I answer: yawmaʾidhin (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">يومئذ</bdi>) substitutes for idhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">إذا</bdi>), and tuḥaddithu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تحدّث</bdi>), “it tells,” governs both. Alternatively, idhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">إذا</bdi>) may be governed by an omitted verb, and yawmaʾidhin (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">يومئذ</bdi>) by tuḥaddithu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تحدّث</bdi>).</p><p>If you ask where the two objects of tuḥaddithu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تحدّث</bdi>) are, I answer: the first is omitted and the second is “its tidings.” The underlying expression is “it tells created beings its tidings.” But the aim is to mention its telling the tidings, not to mention created beings, in order to magnify the day.</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.04","heading":"T099.04 — Does “tell” take one object, two, or three? [XVI:539–540]","text":"On “where are the two objects of ‘it tells’?”: it is said that both question and answer are open to examination. Ḥaddatha does not take two objects; it takes one. The omitted term explicitly supplied here is the direct object; the expressed term, “its tidings,” is an absolute object, a verbal-noun complement. These are not called “two objects” in the grammarians’ technical usage.\n\nTrue, when the particular content of the verbal noun is mentioned in this construction, it is made accusative. Some grammarians then call its components a second and third object, as in “I told Zayd that ʿAmr was standing,” and call the verb transitive to three objects. It has been stated and established in its proper place that this is not so: the verb takes one object, while “Zayd standing” is accusative because it occupies the place of the verbal noun. But when the verbal noun is explicitly expressed, as in “I told him a telling and a report,” no one says that the verb takes two objects.\n\nThe proof is that, after explaining that “Zayd standing” is accusative in such a construction because it occupies the place of a verbal noun, rather than being a second and third object, Ibn al-Ḥājib says: “It remains to ask how something that is not an action in meaning—the supposed second and third objects—can occupy the position of a verbal noun.” He answers: “It was not a verbal noun insofar as it was ‘Zayd standing,’ but insofar as it was a particular report. The aspect that permits it to be predicated of ‘the report’ when you say, ‘Zayd told me that ʿAmr was departing,’ is the same aspect that permits it to occupy the place of a verbal noun.”\n\nI say: one may answer that ḥaddatha (حدّث) and its sister verbs truly take one object, and that making them take three or two involves figurative extension or incorporation of another verb’s meaning. Al-Mufaṣṣal says: “Ḥaddathtu is treated like aʿlamtu (أعلمت), ‘I informed,’ because it agrees with it in meaning, and is therefore made transitive in the same way.” The author of al-Iqlīd says: “Anbaʾa, nabbaʾa (نبّأ), akhbara, and khabbara originally take one object: anbaʾtu (أنبأت) Zaydan bi-kadhā (بكذا), ‘I informed Zayd of such-and-such.’ The preposition is then omitted and one says anbaʾtuhu (أنبأته) kadhā (كذا). In revelation, ‘Who informed you of this?’ [66:3] means bi-hādhā (بهذا), ‘of this’; and ‘Inform My servants that I am the Forgiving, the Merciful’ [15:49]. When these verbs take three objects, this is only because they are treated like aʿlamtu (أعلمت).”\n\nIt is therefore clear that the author’s question rests on this analysis. His answer indicates it when he explicitly says: “As though it were said, ‘On that day it tells its tidings: that your Lord has inspired it,’ because one says both ‘I told him such-and-such’ and ‘I told him of such-and-such.’”","title":"Does “tell” take one object, two, or three? [XVI:539–540]","author":"tibi","on":["K099.04"],"anchor":"K099.04","surah":99,"ar":"قوله: (أين مفعولا ﴿تُحَدِّثُ﴾؟ )، قيل: في السؤال والجواب نظر، لأن \"حدث\" ليس متعدياً إلى مفعولين، بل هو متعد إلى مفعول واحد، والمحذوف الذي صرح بذكره هاهنا هو المفعول به، وأما المذكور وهو ﴿أَخْبَارَهَا﴾ فمفعول مطلق، وهما لا يُسميان مفعولين في اصطلاح النحاة.\n\nنعم، إذا ذُكرت خصوصية المصدر في هذا الباب جُعل منصوباً، ويسميه بعض النحاة حينئذ مفعولاً ثانياً وثالثاً، نحو: حدثت زيداً عمراً قائماً، ويقال حينئذ: هو متعد إلى ثلاثة مفاعيل، وقد ذُكر وحُقق في موضعه أنه ليس كذلك، وأنه متعد إلى واحد، وأن \"زيداً قائماً\" نصبا لوقوعهما موقع المصدر. وأما إذا ذُكر المصدر بلفظه نحو: حدثته حديثاً وخبراً، فلا يقول أحد/ إنه متعد إلى مفعولين.\n\nوالدليل على ما ذكرنا أن ابن الحاجب بعدما بين أن \"زيداً قائماً\" نُصب في مثل هذا الموضع لوقوعه موقع المصدر، لا لكونه مفعولاً ثانياً وثالثاً، قال: \"بقى أن يقال: كيف يصح أن يقع ما ليس بفعل في المعنى مصدراً، وهو المفعول الثاني والثالث؟ \" ثم قال: \"والجواب عنه أنه لم يكن مصدراً باعتبار كونه زيداً قائماً، ولكن باعتبار كونه حديثاً مخصوصاً، فالوجه الذي صح الإخبار به عن الحديث إذا قلت: حدثني زيد عمرو منطلق، هو الذي صحح وقوعه مصدراً\".\n\nوقلت: ويمكن أن يقال: إن \"حدثت وأخواتها\" متعديات إلى مفعول واحد حقيقة، وجعلها متعديات إلى ثلاثة أو إلى اثنين تجوز أو تضمين؛ قال في \"المفصل\": \"حدثت\n\nأُجري مجرى أعلمت لموافقته له في معناه، فعُدي بتعديه\". قال صاحب \"الإقليد\": \"الأصل في أنبأ ونبأ، وأخبر وخبر، التعدي إلى مفعول واحد، نحو: أنبأت زيداً بكذا، ثم حُذف الجار فيقال: أنبأته كذا، وفي التنزيل: ﴿مَنْ أَنبَأَكَ هَذَا﴾ [التحريم: 3]، أي: بهذا، ﴿نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ﴾ [الحجر: 49]؛ فإذا عُديت إلى ثلاثة، فليس إلا لإجرائها مجرى أعلمت\".\n\nفظهر أن سؤال المصنف مبني على هذا، وجوابه يدل عليه حيث صرح بقوله: \"كأنه قيل: يومئذ تحدث أخبارها، بأن ربك أوحى لها؛ لأنك تقول: حدثته كذا وحدثته بكذا\".","html":"<p>On “where are the two objects of ‘it tells’?”: it is said that both question and answer are open to examination. Ḥaddatha does not take two objects; it takes one. The omitted term explicitly supplied here is the direct object; the expressed term, “its tidings,” is an absolute object, a verbal-noun complement. These are not called “two objects” in the grammarians’ technical usage.</p><p>True, when the particular content of the verbal noun is mentioned in this construction, it is made accusative. Some grammarians then call its components a second and third object, as in “I told Zayd that ʿAmr was standing,” and call the verb transitive to three objects. It has been stated and established in its proper place that this is not so: the verb takes one object, while “Zayd standing” is accusative because it occupies the place of the verbal noun. But when the verbal noun is explicitly expressed, as in “I told him a telling and a report,” no one says that the verb takes two objects.</p><p>The proof is that, after explaining that “Zayd standing” is accusative in such a construction because it occupies the place of a verbal noun, rather than being a second and third object, Ibn al-Ḥājib says: “It remains to ask how something that is not an action in meaning—the supposed second and third objects—can occupy the position of a verbal noun.” He answers: “It was not a verbal noun insofar as it was ‘Zayd standing,’ but insofar as it was a particular report. The aspect that permits it to be predicated of ‘the report’ when you say, ‘Zayd told me that ʿAmr was departing,’ is the same aspect that permits it to occupy the place of a verbal noun.”</p><p>I say: one may answer that ḥaddatha (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">حدّث</bdi>) and its sister verbs truly take one object, and that making them take three or two involves figurative extension or incorporation of another verb’s meaning. Al-Mufaṣṣal says: “Ḥaddathtu is treated like aʿlamtu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أعلمت</bdi>), ‘I informed,’ because it agrees with it in meaning, and is therefore made transitive in the same way.” The author of al-Iqlīd says: “Anbaʾa, nabbaʾa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">نبّأ</bdi>), akhbara, and khabbara originally take one object: anbaʾtu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أنبأت</bdi>) Zaydan bi-kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بكذا</bdi>), ‘I informed Zayd of such-and-such.’ The preposition is then omitted and one says anbaʾtuhu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أنبأته</bdi>) kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كذا</bdi>). In revelation, ‘Who informed you of this?’ [66:3] means bi-hādhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بهذا</bdi>), ‘of this’; and ‘Inform My servants that I am the Forgiving, the Merciful’ [15:49]. When these verbs take three objects, this is only because they are treated like aʿlamtu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أعلمت</bdi>).”</p><p>It is therefore clear that the author’s question rests on this analysis. His answer indicates it when he explicitly says: “As though it were said, ‘On that day it tells its tidings: that your Lord has inspired it,’ because one says both ‘I told him such-and-such’ and ‘I told him of such-and-such.’”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.05","heading":"T099.05 — Why the hearers are omitted [XVI:540]","text":"On “the aim is to mention its telling the tidings”: the purpose in the verse is the second object, not the first, because the sūrah is directed toward the terror of the Resurrection. That is: a tremendous day on which inanimate things speak.","title":"Why the hearers are omitted [XVI:540]","author":"tibi","on":["K099.04"],"anchor":"K099.04","surah":99,"ar":"قوله: (إلا أن المقصود ذكر تحديثها الأخبار)، أي: الغرض في الآية هو المفعول الثاني لا الأول، لأن السورة مسوقة في هول القيامة، أي: يوم عظيم تحدث فيه الجمادات.","html":"<p>On “the aim is to mention its telling the tidings”: the purpose in the verse is the second object, not the first, because the sūrah is directed toward the terror of the Resurrection. That is: a tremendous day on which inanimate things speak.</p>","lemma":"إلا أن المقصود ذكر تحديثها الأخبار","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:1","number":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","en":"When Earth is shaken with her (final) earthquake"},{"key":"99:2","number":2,"ar":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","en":"And Earth yieldeth up her burdens"},{"key":"99:3","number":3,"ar":"وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا","en":"And man saith: What aileth her"},{"key":"99:4","number":4,"ar":"يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا","en":"That day she will relate her chronicles"}],"quran_ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا ﴿1﴾ وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا ﴿2﴾ وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا ﴿3﴾ يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿4﴾","quran_en":"1. When Earth is shaken with her (final) earthquake 2. And Earth yieldeth up her burdens 3. And man saith: What aileth her 4. That day she will relate her chronicles"},{"id":"K099.05","q":"99:5","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · “Because your Lord has inspired it”","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"“Because your Lord has inspired it” [IV:784]","html":"<p>If you ask what the bāʾ (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ب</bdi>) in “because your Lord” depends on, I answer: on “it tells.” The meaning is: it tells its tidings because your Lord inspired it and commanded it to tell.</p><p>The meaning may also be: on that day, by telling that your Lord has inspired it, it tells its tidings—on the understanding that its telling that your Lord has inspired it is itself the telling of its tidings. Compare your saying, “You have given me every counsel by counselling me about religion.”</p><p>“Because your Lord” may also substitute for “its tidings,” as though it were said, “On that day it tells of its tidings: that your Lord has inspired it,” because you can say both ḥaddathtuhu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">حدّثته</bdi>) kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كذا</bdi>) and ḥaddathtuhu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">حدّثته</bdi>) bi-kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بكذا</bdi>), “I told him such-and-such.”</p><p>Awḥā lahā means awḥā ilayhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أوحى إليها</bdi>), “inspired it.” It is figurative, like “that We say to it, ‘Be,’ and it is” [cf. 16:40; 36:82]. The poet says:\n“He inspired it to be still, and it became still.”</p><p>Ibn Masʿūd read tunabbiʾu akhbārahā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تُنَبِّئُ أخبارها</bdi>), “it reports its tidings”; Saʿīd ibn Jubayr read tunbiʾu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تُنْبِئُ</bdi>), without doubling the consonant.</p>","author":"kashshaf","source_id":"K099.05"},{"type":"exposition","title":"Abstraction and the inspiration of the earth [XVI:540–541]","html":"<p>On “on that day, by telling that your Lord has inspired it, it tells its tidings”: apparently the bāʾ (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ب</bdi>) here resembles that in “If you meet so-and-so, you will meet in him a man of consummate goodness.” The meaning is: by telling that your Lord has inspired it, the earth tells its tidings in their utmost degree. This therefore belongs to abstraction, tajrīd (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تجريد</bdi>). Hence he says: “On the understanding that its telling that your Lord has inspired it is itself the telling of its tidings.”</p><p>Under His words, “When We took from the prophets their covenant,” down to “and We took from them a solemn covenant” [33:7], he says: “By the second He intends precisely the first: by that covenant We took from them a solemn covenant.” The same applies to the example “You gave me every counsel by counselling me about religion”: from counsel concerning religion he abstracts perfect counsel. So too the poet says:\n“She granted me all my wishes with a visit,\nsnatched in secret like the darting of a bird.\nHad I been able, I would have bestowed upon the darkness\nthe blackness of my pupil, to lengthen our night.”</p><p>On “it is figurative”: that is, an extended metaphor, as previously under “Be, and it is.” The will to manifest the states within the earth is likened to an instruction conveyed to someone commanded, to display the swiftness with which what is wanted of him is obeyed.</p>","author":"tibi","source_id":"T099.06"}],"types":["exposition","language","theology","reports"],"ar":"فإن قلت: بم تعلقت الباء في قوله بأن ربك؟ قلت، بتحدث، معناه: تحدث أخبارها بسبب إيحاء ربك لها، وأمره إياها بالتحديث. ويجوز أن يكون المعنى: يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها، على أن تحديثها بأن ربك أوحى لها: تحديث بأخبارها، كما تقول: نصحتني كل نصيحة، بأن نصحتني في الدين. ويجوز أن يكون بأن ربك بدلا من أخبارها كأنه قيل: يومئذ تحدث بأخبارها بأن ربك أوحى لها، لأنك تقول: حدثته كذا وحدثته بكذا. وأوحى لها بمعنى أوحى إليها، وهو مجاز كقوله أن نقول له كن فيكون قال: أوحى لها القرار فاستقرت وقرأ ابن مسعود: تنبئ أخبارها، وسعيد بن جبير: تنبئ، بالتخفيف.\n\nقوله: (يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها)، والظاهر أن الباء على هذا كالباء في قولك: لئن لقيت فلاناً، لتلقين به رجلاً متناهياً في الخير. المعنى: يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها المتناهية في بابها، فيكون من باب التجريد، ولذلك قال: \"على أن تحديثها بأن ربك أوحى لها: تحديث بأخبارها\"؛ قال في قوله تعالى: ﴿وَإِذْ أَخَذْنَا مِنَ النَّبِيِّينَ مِيثَاقَهُمْ﴾ إلى قوله: ﴿وَأَخَذْنَا مِنْهُم مِّيثَاقًا غَلِيظًا﴾ [الأحزاب: 7]: \"أراد\n\nبالثاني الأول بعينه، أي: أخذنا منهم بذلك الميثاق ميثاقاً غليظاً، وعليه المثال: نصحتني بكل نصيحة، بأن نصحتني في الدين؛ جرد من النصحية في الدين النصيحة الكاملة، وعليه قول الشاعر:\n\nفأنالني كل المنى بزيارة كانت مخالسة كخطفة طائر\n\nفلو استطعت إذا خلعت على الدجى لتطول ليلتنا سواد الناظر\n\nقوله: (وهو مجاز)، أي استعارة تمثيلية كما سبق في قوله: ﴿كُن فَيَكُونُ﴾؛ شبه إرادة إظهار ما فيها من الأحوال بما يُلقى إلى المأمور، لإظهار ما يراد منه من سرعة الامتثال.","layers":[{"id":"K099.05","heading":"K099.05 — “Because your Lord has inspired it” [IV:784]","text":"If you ask what the bāʾ (ب) in “because your Lord” depends on, I answer: on “it tells.” The meaning is: it tells its tidings because your Lord inspired it and commanded it to tell.\n\nThe meaning may also be: on that day, by telling that your Lord has inspired it, it tells its tidings—on the understanding that its telling that your Lord has inspired it is itself the telling of its tidings. Compare your saying, “You have given me every counsel by counselling me about religion.”\n\n“Because your Lord” may also substitute for “its tidings,” as though it were said, “On that day it tells of its tidings: that your Lord has inspired it,” because you can say both ḥaddathtuhu (حدّثته) kadhā (كذا) and ḥaddathtuhu (حدّثته) bi-kadhā (بكذا), “I told him such-and-such.”\n\nAwḥā lahā means awḥā ilayhā (أوحى إليها), “inspired it.” It is figurative, like “that We say to it, ‘Be,’ and it is” [cf. 16:40; 36:82]. The poet says:\n“He inspired it to be still, and it became still.”\n\nIbn Masʿūd read tunabbiʾu akhbārahā (تُنَبِّئُ أخبارها), “it reports its tidings”; Saʿīd ibn Jubayr read tunbiʾu (تُنْبِئُ), without doubling the consonant.","title":"“Because your Lord has inspired it” [IV:784]","author":"kashshaf","surah":99,"ar":"فإن قلت: بم تعلقت الباء في قوله بأن ربك؟ قلت، بتحدث، معناه: تحدث أخبارها بسبب إيحاء ربك لها، وأمره إياها بالتحديث. ويجوز أن يكون المعنى: يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها، على أن تحديثها بأن ربك أوحى لها: تحديث بأخبارها، كما تقول: نصحتني كل نصيحة، بأن نصحتني في الدين. ويجوز أن يكون بأن ربك بدلا من أخبارها كأنه قيل: يومئذ تحدث بأخبارها بأن ربك أوحى لها، لأنك تقول: حدثته كذا وحدثته بكذا. وأوحى لها بمعنى أوحى إليها، وهو مجاز كقوله أن نقول له كن فيكون قال: أوحى لها القرار فاستقرت وقرأ ابن مسعود: تنبئ أخبارها، وسعيد بن جبير: تنبئ، بالتخفيف.","html":"<p>If you ask what the bāʾ (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ب</bdi>) in “because your Lord” depends on, I answer: on “it tells.” The meaning is: it tells its tidings because your Lord inspired it and commanded it to tell.</p><p>The meaning may also be: on that day, by telling that your Lord has inspired it, it tells its tidings—on the understanding that its telling that your Lord has inspired it is itself the telling of its tidings. Compare your saying, “You have given me every counsel by counselling me about religion.”</p><p>“Because your Lord” may also substitute for “its tidings,” as though it were said, “On that day it tells of its tidings: that your Lord has inspired it,” because you can say both ḥaddathtuhu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">حدّثته</bdi>) kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">كذا</bdi>) and ḥaddathtuhu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">حدّثته</bdi>) bi-kadhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">بكذا</bdi>), “I told him such-and-such.”</p><p>Awḥā lahā means awḥā ilayhā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">أوحى إليها</bdi>), “inspired it.” It is figurative, like “that We say to it, ‘Be,’ and it is” [cf. 16:40; 36:82]. The poet says:\n“He inspired it to be still, and it became still.”</p><p>Ibn Masʿūd read tunabbiʾu akhbārahā (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تُنَبِّئُ أخبارها</bdi>), “it reports its tidings”; Saʿīd ibn Jubayr read tunbiʾu (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تُنْبِئُ</bdi>), without doubling the consonant.</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.06","heading":"T099.06 — Abstraction and the inspiration of the earth [XVI:540–541]","text":"On “on that day, by telling that your Lord has inspired it, it tells its tidings”: apparently the bāʾ (ب) here resembles that in “If you meet so-and-so, you will meet in him a man of consummate goodness.” The meaning is: by telling that your Lord has inspired it, the earth tells its tidings in their utmost degree. This therefore belongs to abstraction, tajrīd (تجريد). Hence he says: “On the understanding that its telling that your Lord has inspired it is itself the telling of its tidings.”\n\nUnder His words, “When We took from the prophets their covenant,” down to “and We took from them a solemn covenant” [33:7], he says: “By the second He intends precisely the first: by that covenant We took from them a solemn covenant.” The same applies to the example “You gave me every counsel by counselling me about religion”: from counsel concerning religion he abstracts perfect counsel. So too the poet says:\n“She granted me all my wishes with a visit,\nsnatched in secret like the darting of a bird.\nHad I been able, I would have bestowed upon the darkness\nthe blackness of my pupil, to lengthen our night.”\n\nOn “it is figurative”: that is, an extended metaphor, as previously under “Be, and it is.” The will to manifest the states within the earth is likened to an instruction conveyed to someone commanded, to display the swiftness with which what is wanted of him is obeyed.","title":"Abstraction and the inspiration of the earth [XVI:540–541]","author":"tibi","on":["K099.05"],"anchor":"K099.05","surah":99,"ar":"قوله: (يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها)، والظاهر أن الباء على هذا كالباء في قولك: لئن لقيت فلاناً، لتلقين به رجلاً متناهياً في الخير. المعنى: يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها المتناهية في بابها، فيكون من باب التجريد، ولذلك قال: \"على أن تحديثها بأن ربك أوحى لها: تحديث بأخبارها\"؛ قال في قوله تعالى: ﴿وَإِذْ أَخَذْنَا مِنَ النَّبِيِّينَ مِيثَاقَهُمْ﴾ إلى قوله: ﴿وَأَخَذْنَا مِنْهُم مِّيثَاقًا غَلِيظًا﴾ [الأحزاب: 7]: \"أراد\n\nبالثاني الأول بعينه، أي: أخذنا منهم بذلك الميثاق ميثاقاً غليظاً، وعليه المثال: نصحتني بكل نصيحة، بأن نصحتني في الدين؛ جرد من النصحية في الدين النصيحة الكاملة، وعليه قول الشاعر:\n\nفأنالني كل المنى بزيارة كانت مخالسة كخطفة طائر\n\nفلو استطعت إذا خلعت على الدجى لتطول ليلتنا سواد الناظر\n\nقوله: (وهو مجاز)، أي استعارة تمثيلية كما سبق في قوله: ﴿كُن فَيَكُونُ﴾؛ شبه إرادة إظهار ما فيها من الأحوال بما يُلقى إلى المأمور، لإظهار ما يراد منه من سرعة الامتثال.","html":"<p>On “on that day, by telling that your Lord has inspired it, it tells its tidings”: apparently the bāʾ (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ب</bdi>) here resembles that in “If you meet so-and-so, you will meet in him a man of consummate goodness.” The meaning is: by telling that your Lord has inspired it, the earth tells its tidings in their utmost degree. This therefore belongs to abstraction, tajrīd (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">تجريد</bdi>). Hence he says: “On the understanding that its telling that your Lord has inspired it is itself the telling of its tidings.”</p><p>Under His words, “When We took from the prophets their covenant,” down to “and We took from them a solemn covenant” [33:7], he says: “By the second He intends precisely the first: by that covenant We took from them a solemn covenant.” The same applies to the example “You gave me every counsel by counselling me about religion”: from counsel concerning religion he abstracts perfect counsel. So too the poet says:\n“She granted me all my wishes with a visit,\nsnatched in secret like the darting of a bird.\nHad I been able, I would have bestowed upon the darkness\nthe blackness of my pupil, to lengthen our night.”</p><p>On “it is figurative”: that is, an extended metaphor, as previously under “Be, and it is.” The will to manifest the states within the earth is likened to an instruction conveyed to someone commanded, to display the swiftness with which what is wanted of him is obeyed.</p>","lemma":"يومئذ تحدث بتحديث أن ربك أوحى لها أخبارها","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:5","number":5,"ar":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","en":"Because thy Lord inspireth her"}],"quran_ar":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا ﴿5﴾","quran_en":"5. Because thy Lord inspireth her"},{"id":"K099.06","q":"99:6","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · Separate departures and the order of the verses","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"Separate departures and the order of the verses [IV:784–785]","html":"<p>They come forth from the exits of their graves to the standing-place “separately”: some white-faced and secure, others black-faced and frightened. Or they leave the standing-place separately, divided between the paths of Paradise and the Fire, to be shown the recompense of their deeds.</p><p>In the Prophet’s reading, li-yaraw has fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>): “so that they may see.” Ibn ʿAbbās and Zayd ibn ʿAlī read yurahu with ḍamma (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ضَمّة</bdi>): “he will be shown it.” It is related that a Bedouin put the words “good, he will see it” later [than the corresponding clause about evil]. When told, “You have put one part before and another after,” he replied:\n“Take the hollow of Harshā or its back:\neither side of Harshā is a road for them.”</p>","author":"kashshaf","source_id":"K099.06"},{"type":"exposition","title":"Harshā and the priority of good [XVI:542]","html":"<p>On the line “Take the hollow of Harshā”: Harshā is a pass on the road to Mecca, near al-Juḥfa, with two routes. He addresses his two companions: travel through the hollow of this pass or along its back, since both sides are roads for the camels. This is a proverb for a course equally easy from either side.</p><p>It is said that the Bedouin imagined rearrangement here to be permissible. This is wrong: he overlooked the Qurʾān’s subtleties. There is no point in adducing the line here, and it would have been better to omit it, because primary concern attaches to good, while evil is incidental. Under “Whoever disbelieves, his unbelief is against him; and whoever acts righteously, they prepare for themselves—so that He may reward those who believe and do righteous deeds from His bounty; He does not love the unbelievers” [30:44–45], the Qāḍī says: “‘So that He may reward’ gives the purpose of ‘they prepare.’ Limiting the mention to the believer’s reward indicates that this is what is intended in itself.”</p>","author":"tibi","source_id":"T099.07"}],"types":["exposition","language","theology","reports"],"ar":"يصدرون عن مخارجهم من القبور إلى الموقف أشتاتا بيض الوجوه آمنين، وسود الوجوه فزعين. أو يصدرون عن الموقف أشتاتا يتفرق بهم طريقا الجنة والنار، ليروا جزاء أعمالهم. وفي قراءة النبي صلى الله عليه وسلم: ليروا بالفتح. وقرأ ابن عباس وزيد بن على: يره، بالضم. ويحكى أن أعرابيا أخر خيرا يره فقيل له، قدمت وأخرت، فقال: خذا بطن هرشى أو قفاها فإنه ... كلا جانبي هرشى لهن طريق\n\nقوله: (خُذا بطن هَرشى) البيت، هَرشى: عقبة في طريق مكة قريبة من \"الجُحفة\" لها طريقان؛ يخاطب صاحبيه ويقول لهما: سيرا في بطن هذه الثنية أو في قفاها، فإن كلا الجانبين طريقاً للإبل، وهذا مثل فيما سهل الطريق من الجانبين.\n\nقيل: كان الأعرابي ظن أن التقديم والتأخير في هذا الموضع جائز وهو خطأ، فإنه غفل عن اللطائف القرآنية، ولا معنى لإيراد البيت في هذا المقام، فكان تركه أولى؛ لأن العناية منوطة بالخير، والشر عارض، قال القاضي في قوله تعالى: ﴿مَن كَفَرَ فَعَلَيْهِ كُفْرُهُ وَمَنْ عَمِلَ صَالِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ (لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِن فَضْلِهِ إِنَّهُ لَا يُحِبُّ الْكَافِرِينَ﴾ [الروم: 44 - 45]: \" ﴿لِيَجْزِيَ﴾ علة لـ ﴿يَمْهَدُونَ﴾، والاقتصار على جزاء المؤمن للإشعار بأنه المقصود بالذات\".","layers":[{"id":"K099.06","heading":"K099.06 — Separate departures and the order of the verses [IV:784–785]","text":"They come forth from the exits of their graves to the standing-place “separately”: some white-faced and secure, others black-faced and frightened. Or they leave the standing-place separately, divided between the paths of Paradise and the Fire, to be shown the recompense of their deeds.\n\nIn the Prophet’s reading, li-yaraw has fatḥa (فَتْحة): “so that they may see.” Ibn ʿAbbās and Zayd ibn ʿAlī read yurahu with ḍamma (ضَمّة): “he will be shown it.” It is related that a Bedouin put the words “good, he will see it” later [than the corresponding clause about evil]. When told, “You have put one part before and another after,” he replied:\n“Take the hollow of Harshā or its back:\neither side of Harshā is a road for them.”","title":"Separate departures and the order of the verses [IV:784–785]","author":"kashshaf","surah":99,"ar":"يصدرون عن مخارجهم من القبور إلى الموقف أشتاتا بيض الوجوه آمنين، وسود الوجوه فزعين. أو يصدرون عن الموقف أشتاتا يتفرق بهم طريقا الجنة والنار، ليروا جزاء أعمالهم. وفي قراءة النبي صلى الله عليه وسلم: ليروا بالفتح. وقرأ ابن عباس وزيد بن على: يره، بالضم. ويحكى أن أعرابيا أخر خيرا يره فقيل له، قدمت وأخرت، فقال: خذا بطن هرشى أو قفاها فإنه ... كلا جانبي هرشى لهن طريق","html":"<p>They come forth from the exits of their graves to the standing-place “separately”: some white-faced and secure, others black-faced and frightened. Or they leave the standing-place separately, divided between the paths of Paradise and the Fire, to be shown the recompense of their deeds.</p><p>In the Prophet’s reading, li-yaraw has fatḥa (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">فَتْحة</bdi>): “so that they may see.” Ibn ʿAbbās and Zayd ibn ʿAlī read yurahu with ḍamma (<bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">ضَمّة</bdi>): “he will be shown it.” It is related that a Bedouin put the words “good, he will see it” later [than the corresponding clause about evil]. When told, “You have put one part before and another after,” he replied:\n“Take the hollow of Harshā or its back:\neither side of Harshā is a road for them.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.07","heading":"T099.07 — Harshā and the priority of good [XVI:542]","text":"On the line “Take the hollow of Harshā”: Harshā is a pass on the road to Mecca, near al-Juḥfa, with two routes. He addresses his two companions: travel through the hollow of this pass or along its back, since both sides are roads for the camels. This is a proverb for a course equally easy from either side.\n\nIt is said that the Bedouin imagined rearrangement here to be permissible. This is wrong: he overlooked the Qurʾān’s subtleties. There is no point in adducing the line here, and it would have been better to omit it, because primary concern attaches to good, while evil is incidental. Under “Whoever disbelieves, his unbelief is against him; and whoever acts righteously, they prepare for themselves—so that He may reward those who believe and do righteous deeds from His bounty; He does not love the unbelievers” [30:44–45], the Qāḍī says: “‘So that He may reward’ gives the purpose of ‘they prepare.’ Limiting the mention to the believer’s reward indicates that this is what is intended in itself.”","title":"Harshā and the priority of good [XVI:542]","author":"tibi","on":["K099.06"],"anchor":"K099.06","surah":99,"ar":"قوله: (خُذا بطن هَرشى) البيت، هَرشى: عقبة في طريق مكة قريبة من \"الجُحفة\" لها طريقان؛ يخاطب صاحبيه ويقول لهما: سيرا في بطن هذه الثنية أو في قفاها، فإن كلا الجانبين طريقاً للإبل، وهذا مثل فيما سهل الطريق من الجانبين.\n\nقيل: كان الأعرابي ظن أن التقديم والتأخير في هذا الموضع جائز وهو خطأ، فإنه غفل عن اللطائف القرآنية، ولا معنى لإيراد البيت في هذا المقام، فكان تركه أولى؛ لأن العناية منوطة بالخير، والشر عارض، قال القاضي في قوله تعالى: ﴿مَن كَفَرَ فَعَلَيْهِ كُفْرُهُ وَمَنْ عَمِلَ صَالِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ (لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِن فَضْلِهِ إِنَّهُ لَا يُحِبُّ الْكَافِرِينَ﴾ [الروم: 44 - 45]: \" ﴿لِيَجْزِيَ﴾ علة لـ ﴿يَمْهَدُونَ﴾، والاقتصار على جزاء المؤمن للإشعار بأنه المقصود بالذات\".","html":"<p>On the line “Take the hollow of Harshā”: Harshā is a pass on the road to Mecca, near al-Juḥfa, with two routes. He addresses his two companions: travel through the hollow of this pass or along its back, since both sides are roads for the camels. This is a proverb for a course equally easy from either side.</p><p>It is said that the Bedouin imagined rearrangement here to be permissible. This is wrong: he overlooked the Qurʾān’s subtleties. There is no point in adducing the line here, and it would have been better to omit it, because primary concern attaches to good, while evil is incidental. Under “Whoever disbelieves, his unbelief is against him; and whoever acts righteously, they prepare for themselves—so that He may reward those who believe and do righteous deeds from His bounty; He does not love the unbelievers” [30:44–45], the Qāḍī says: “‘So that He may reward’ gives the purpose of ‘they prepare.’ Limiting the mention to the believer’s reward indicates that this is what is intended in itself.”</p>","lemma":"خذا بطن هرشى","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:6","number":6,"ar":"يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ","en":"That day mankind will issue forth in scattered groups to be shown their deeds"}],"quran_ar":"يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ ﴿6﴾","quran_en":"6. That day mankind will issue forth in scattered groups to be shown their deeds"},{"id":"K099.07","q":"99:7–8","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · The atom’s weight and the two groups","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"The atom’s weight and the two groups [IV:785]","html":"<p>A dharra is a small ant. It is also said that dharr is the dust visible in a beam of sunlight.</p><p>If you ask, “The unbeliever’s good deeds are nullified by unbelief, and the believer’s evil deeds are pardoned through avoiding major sins: what, then, is the meaning of recompense for atom-weights of good and evil?”—I answer: the meaning is “whoever does an atom’s weight of good” from the company of the felicitous, and “whoever does an atom’s weight of evil” from the company of the wretched, because this follows “people will come forth separately.”</p>","author":"kashshaf","source_id":"K099.07"},{"type":"exposition","title":"The restricted reading and objections to its premises [XVI:542–543]","html":"<p>On “because this follows ‘On that day people will come forth separately’”: he means that “Whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it” sets out the division of people into two groups, the felicitous and the wretched. That is, the verse is restricted in scope.</p><p>Al-Intiṣāf says: “His question rests on two principles. The first is that the unbeliever’s good deeds are nullified by unbelief. This needs examination. If it means that he receives no reward for them, it is correct. But if it means that they do not lessen punishment, that is not conceded. Reports have come concerning Ḥātim, that God lightens his punishment for his generosity, and concerning Abū Ṭālib and others. Such deeds therefore have an effect in lessening punishment.</p><p>“The second is that avoiding major sins necessarily expiates minor ones. This conflicts with the doctrine of the People of the Sunna. Minor sins are expiated by one of two things: repentance, or God’s willing forgiveness. This question therefore falls away according to us.”</p><p>The Imām says: “One may say that, although the unbeliever’s good deeds are nullified by his unbelief, the weighing of deeds is recognized according to your own position. To the extent of those good deeds, punishment for his unbelief is reduced. The same applies on the other side. This therefore does not impair the verse’s generality.”</p>","author":"tibi","source_id":"T099.08"},{"type":"exposition","title":"Two possible scopes and the author’s doctrinal intention [XVI:543–544]","html":"<p>I say: the verse admits two meanings. One paired clause may intend the felicitous and the other the wretched, since the relative expression is repeated. Or each clause may intend generality: whoever among believers and unbelievers does an atom’s weight of good will see it, and whoever among believers and unbelievers does an atom’s weight of evil will see it.</p><p>The author’s words follow the first interpretation, as does what Muḥyī al-Sunna [al-Baghawī] and the Imām transmit from Muḥammad ibn Kaʿb al-Quraẓī: whoever does an atom’s weight of good while an unbeliever sees its reward in this world—in himself, his family, and his property—until he meets the hereafter with no good awaiting him there. Whoever does an atom’s weight of evil while a believer has it expiated in this world—in himself, his family, and his property—until he reaches the hereafter with no evil awaiting him there.</p><p>But the author’s intention is to include the person committing a major sin among the unbelievers and the wretched, because that person’s good deeds are nullified by it and he therefore sees only evil; just as the minor sins of one avoiding major sins are expiated through that avoidance and he sees only good. This is known from his question.</p><p>On the second interpretation comes what al-Wāḥidī transmits from Muqātil: whoever does an atom’s weight of good in this world will see it on the Day of Resurrection and rejoice in it. Likewise with evil: he sees it in his record, and it grieves him. Muḥyī al-Sunna and the Imām transmit from Ibn ʿAbbās: no believer or unbeliever does anything, good or evil, without God showing it to him. The believer’s evil deeds are forgiven and he is rewarded for his good deeds; the unbeliever’s good deeds are rejected and he is punished for his evil deeds.</p>","author":"tibi","source_id":"T099.09"},{"type":"exposition","title":"Wording, meaning, and style favour generality [XVI:544–545]","html":"<p>This latter possibility is supported by the wording, the meaning, and the style.</p><p>As for the wording: “Whoever does,” as already stated, elaborates the preceding “People will come forth separately, to be shown their deeds,” so the two must agree. “Their deeds” is a plural in a possessive construction and conveys comprehensiveness and inclusion of all. “People will come forth” is qualified by “separately,” indicating that they take diverse routes to settle in their stations in Paradise and the Fire according to their differing deeds. Hence Paradise has ascending degrees and the Fire descending levels.</p><p>As for the meaning: the passage explains the exhaustive display of deeds and their recompense, as in His saying, “We shall set up the just scales for the Day of Resurrection, and no soul will be wronged in anything. Even if it is the weight of a mustard seed, We shall bring it; and We suffice as reckoners” [21:47].</p><p>As for the style: this is one of the comprehensive statements containing the benefits of religion, both its foundations and its branches. We have transmitted from al-Bukhārī and Muslim, from Abū Hurayra, that God’s Messenger was asked about donkeys and said, “Nothing has been revealed to me concerning them except this comprehensive, unique verse,” and recited it. “About donkeys” means about alms on donkeys. Fādhdha, “unique,” means singular in its meaning: a man fadhdha from his companions when he separated from them.</p><p>Imām Aḥmad transmits from Ṣaʿṣaʿa ibn Muʿāwiya, al-Farazdaq’s uncle, that he came to the Prophet, who recited the verse. He said, “That is enough for me; I do not mind hearing nothing else.” In al-Ḥaqāʾiq: a sage was asked, “Admonish us,” and recited the verse. The questioner said, “Then the admonition has reached its utmost.”</p>","author":"tibi","source_id":"T099.10"}],"types":["exposition","language","theology","reports"],"ar":"والذرة: النملة الصغيرة، وقيل «الذر» ما يرى في شعاع الشمس من الهباء. فإن قلت حسنات الكافر محبطة بالكفر، وسيئات المؤمن معفوة باجتناب الكبائر، فما معنى الجزاء بمثاقيل الذر من الخير والشر ؟ قلت: المعنى فمن يعمل مثقال ذرة خيرا: من فريق السعداء. ومن يعمل مثقال ذرة شرا: من فريق الأشقياء، لأنه جاء بعد قوله يصدر الناس أشتاتا،\n\nقوله: (لأنه جاء بعد قوله: ﴿يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا﴾، يعني: ﴿فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ (وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ تفصيل للناس، وهم فريقان: السُّعداء والأشقياء، أي: الآية مختصة.\n\nالانتصاف: \"سؤاله مبني على قاعدتين:\n\nإحداهما: أن حسنات الكافر مُحبطة بالكفر وفيه نظر؛ فإن أريد به أنها لا يثاب بها فصحيح، وأما تخفيف العذاب فغير مُسلم، وقد وردت فيه الأحاديث أن حاتماً يُخفف الله عنه لكرمه، وفي حق أبي طالب وغيره، فلها أثر في تخفيف العذاب.\n\nوثانيتهما: أن اجتناب الكبائر يوجب تكفير الصغائر، فهو خلاف مذهب أهل السنة؛ فتكفير الصغائر بأحد أمرين، إما بالتوبة، وإما بمشيئة الله بالمغفرة؛ فهذا السؤال ساقط عندنا\".\n\nوقال الإمام: \"يجوز أن يقال: إن حسنات الكافر وإن كانت مُحبطة بكفره، لكن الموازنة معتبرة عندكم، فبقدر تلك الحسنات ينحط من عقاب كفره، وكذا القول في الجانب الآخر، فلا يكون ذلك قادحاً في عموم الآية\".\n\nوقلت: الآية تحتمل معنيين: أن يراد بإحدى القرينتين السعداء وبالأخرى الأشقياء لتكرير الموصول، وأن يراد العموم في كل قرينة كما يقال: فمن يعمل مثقال ذرة من المؤمنين والكافرين خيراً يره، ومن يعمل مثقال ذرة من المؤمنين والكافرين شراً يره. وعلى الأول ورد كلام المصنف، وما روى محيي السنة والإمام عن محمد بن كعب القرظي: فمن يعمل مثقال ذرة من خير وهو كافر، فإنه يرى ثواب ذلك في الدنيا في نفسه وأهله وماله، حتى يلقى الآخرة وليس له فيها خير.\n\nومن يعمل مثقال ذرة من شر وهو مؤمن، كُفر ذلك في الدنيا في نفسه وأهله وماله، حتى بلغ الآخرة وليس له فيها شر. لكن قصد المصنف في ذلك إدخال مرتكب الكبيرة في زمرة الكفار والأشقياء، لأن حسنات مرتكب الكبيرة محبطة به فلا يرى غير الشر، كما أن صغائر مجتنب الكبائر مكفرة به، فلا يرى غير الخير، يُعلم ذلك من سؤاله. وعلى الثاني ما رواه الواحدي عن مقاتل: فمن يعمل في الدنيا مثقال ذرة خيراً،\n\nيره يوم القيامة فيفرح به، وكذلك الشر فيراه في كتابه، فيسوؤه ذلك. وروى محيي السنة والإمام عن ابن عباس: ليس من مؤمن ولا كافر عمل خيراً كان أو شراً، إلا أراه الله تعالى إياه؛ فأما المؤمن فتغفر له سيئاته ويُثيبه بحسناته، وأما الكافر فتُرد حسناته ويعذب بسيئاته.\n\nوهذا الاحتمال يساعده النظم والمعنى والأسلوب.\n\nأما النظم، فإن قوله ﴿فَمَن يَعْمَلْ﴾ كما سبق، تفصيل لما عقب به من قوله ﴿يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ﴾، فيجب التوافق. والأعمال جمع مضاف يفيد الشمول والاستغراق، ﴿يَصْدُرُ النَّاسُ﴾ مقيد بقوله ﴿أَشْتَاتًا﴾، فيفيد أنهم على طرائق شتى للنزول في منازلهم من الجنة والنار، بحسب أعمالهم المختلفة، ومن ثم كانت الجنة ذات درجات، والنار ذات دركات.\n\nوأما المعنى، فإنها وردت لبيان الاستقصاء في عرض الأعمال والجزاء عليها، لقوله تعالى: ﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَى بِنَا حَاسِبِينَ﴾ [الأنبياء: 47].\n\nوأما الأسلوب، فإنها من الجوامع الحاوية لفوائد الدين أصولاً وفروعاً، روينا عن البخاري ومسلم عن أبي هريرة: سُئل رسول الله ﷺ عن الحمر، فقال: لم ينزل علي فيها شيء إلا هذه الآية الجامعة الفاذة، فتلاها.\n\nقوله: عن الحُمر، أي: عن صدقة الحُمر. والفاذة: أي المنفردة في معناها؛ فذ الرجل عن أصحابه إذا شذ عنهم. وروى الإمام أحمد عن صعصعة بن معاوية عم الفرزدق، أنه\n\nأتى النبي صلى الله عليه وسلم، فقرأ الآية، فقال: حسبي، لا أبالي أن لا أسمع غيرها. وفي \"الحقائق\": قيل لبعض الحكماء: عظ، فتلا الآية. فقال السائل: فقد انتهت الموعظة.","layers":[{"id":"K099.07","heading":"K099.07 — The atom’s weight and the two groups [IV:785]","text":"A dharra is a small ant. It is also said that dharr is the dust visible in a beam of sunlight.\n\nIf you ask, “The unbeliever’s good deeds are nullified by unbelief, and the believer’s evil deeds are pardoned through avoiding major sins: what, then, is the meaning of recompense for atom-weights of good and evil?”—I answer: the meaning is “whoever does an atom’s weight of good” from the company of the felicitous, and “whoever does an atom’s weight of evil” from the company of the wretched, because this follows “people will come forth separately.”","title":"The atom’s weight and the two groups [IV:785]","author":"kashshaf","surah":99,"ar":"والذرة: النملة الصغيرة، وقيل «الذر» ما يرى في شعاع الشمس من الهباء. فإن قلت حسنات الكافر محبطة بالكفر، وسيئات المؤمن معفوة باجتناب الكبائر، فما معنى الجزاء بمثاقيل الذر من الخير والشر ؟ قلت: المعنى فمن يعمل مثقال ذرة خيرا: من فريق السعداء. ومن يعمل مثقال ذرة شرا: من فريق الأشقياء، لأنه جاء بعد قوله يصدر الناس أشتاتا،","html":"<p>A dharra is a small ant. It is also said that dharr is the dust visible in a beam of sunlight.</p><p>If you ask, “The unbeliever’s good deeds are nullified by unbelief, and the believer’s evil deeds are pardoned through avoiding major sins: what, then, is the meaning of recompense for atom-weights of good and evil?”—I answer: the meaning is “whoever does an atom’s weight of good” from the company of the felicitous, and “whoever does an atom’s weight of evil” from the company of the wretched, because this follows “people will come forth separately.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.08","heading":"T099.08 — The restricted reading and objections to its premises [XVI:542–543]","text":"On “because this follows ‘On that day people will come forth separately’”: he means that “Whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it” sets out the division of people into two groups, the felicitous and the wretched. That is, the verse is restricted in scope.\n\nAl-Intiṣāf says: “His question rests on two principles. The first is that the unbeliever’s good deeds are nullified by unbelief. This needs examination. If it means that he receives no reward for them, it is correct. But if it means that they do not lessen punishment, that is not conceded. Reports have come concerning Ḥātim, that God lightens his punishment for his generosity, and concerning Abū Ṭālib and others. Such deeds therefore have an effect in lessening punishment.\n\n“The second is that avoiding major sins necessarily expiates minor ones. This conflicts with the doctrine of the People of the Sunna. Minor sins are expiated by one of two things: repentance, or God’s willing forgiveness. This question therefore falls away according to us.”\n\nThe Imām says: “One may say that, although the unbeliever’s good deeds are nullified by his unbelief, the weighing of deeds is recognized according to your own position. To the extent of those good deeds, punishment for his unbelief is reduced. The same applies on the other side. This therefore does not impair the verse’s generality.”","title":"The restricted reading and objections to its premises [XVI:542–543]","author":"tibi","on":["K099.07"],"anchor":"K099.07","surah":99,"ar":"قوله: (لأنه جاء بعد قوله: ﴿يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا﴾، يعني: ﴿فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ (وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ تفصيل للناس، وهم فريقان: السُّعداء والأشقياء، أي: الآية مختصة.\n\nالانتصاف: \"سؤاله مبني على قاعدتين:\n\nإحداهما: أن حسنات الكافر مُحبطة بالكفر وفيه نظر؛ فإن أريد به أنها لا يثاب بها فصحيح، وأما تخفيف العذاب فغير مُسلم، وقد وردت فيه الأحاديث أن حاتماً يُخفف الله عنه لكرمه، وفي حق أبي طالب وغيره، فلها أثر في تخفيف العذاب.\n\nوثانيتهما: أن اجتناب الكبائر يوجب تكفير الصغائر، فهو خلاف مذهب أهل السنة؛ فتكفير الصغائر بأحد أمرين، إما بالتوبة، وإما بمشيئة الله بالمغفرة؛ فهذا السؤال ساقط عندنا\".\n\nوقال الإمام: \"يجوز أن يقال: إن حسنات الكافر وإن كانت مُحبطة بكفره، لكن الموازنة معتبرة عندكم، فبقدر تلك الحسنات ينحط من عقاب كفره، وكذا القول في الجانب الآخر، فلا يكون ذلك قادحاً في عموم الآية\".","html":"<p>On “because this follows ‘On that day people will come forth separately’”: he means that “Whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it” sets out the division of people into two groups, the felicitous and the wretched. That is, the verse is restricted in scope.</p><p>Al-Intiṣāf says: “His question rests on two principles. The first is that the unbeliever’s good deeds are nullified by unbelief. This needs examination. If it means that he receives no reward for them, it is correct. But if it means that they do not lessen punishment, that is not conceded. Reports have come concerning Ḥātim, that God lightens his punishment for his generosity, and concerning Abū Ṭālib and others. Such deeds therefore have an effect in lessening punishment.</p><p>“The second is that avoiding major sins necessarily expiates minor ones. This conflicts with the doctrine of the People of the Sunna. Minor sins are expiated by one of two things: repentance, or God’s willing forgiveness. This question therefore falls away according to us.”</p><p>The Imām says: “One may say that, although the unbeliever’s good deeds are nullified by his unbelief, the weighing of deeds is recognized according to your own position. To the extent of those good deeds, punishment for his unbelief is reduced. The same applies on the other side. This therefore does not impair the verse’s generality.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.09","heading":"T099.09 — Two possible scopes and the author’s doctrinal intention [XVI:543–544]","text":"I say: the verse admits two meanings. One paired clause may intend the felicitous and the other the wretched, since the relative expression is repeated. Or each clause may intend generality: whoever among believers and unbelievers does an atom’s weight of good will see it, and whoever among believers and unbelievers does an atom’s weight of evil will see it.\n\nThe author’s words follow the first interpretation, as does what Muḥyī al-Sunna [al-Baghawī] and the Imām transmit from Muḥammad ibn Kaʿb al-Quraẓī: whoever does an atom’s weight of good while an unbeliever sees its reward in this world—in himself, his family, and his property—until he meets the hereafter with no good awaiting him there. Whoever does an atom’s weight of evil while a believer has it expiated in this world—in himself, his family, and his property—until he reaches the hereafter with no evil awaiting him there.\n\nBut the author’s intention is to include the person committing a major sin among the unbelievers and the wretched, because that person’s good deeds are nullified by it and he therefore sees only evil; just as the minor sins of one avoiding major sins are expiated through that avoidance and he sees only good. This is known from his question.\n\nOn the second interpretation comes what al-Wāḥidī transmits from Muqātil: whoever does an atom’s weight of good in this world will see it on the Day of Resurrection and rejoice in it. Likewise with evil: he sees it in his record, and it grieves him. Muḥyī al-Sunna and the Imām transmit from Ibn ʿAbbās: no believer or unbeliever does anything, good or evil, without God showing it to him. The believer’s evil deeds are forgiven and he is rewarded for his good deeds; the unbeliever’s good deeds are rejected and he is punished for his evil deeds.","title":"Two possible scopes and the author’s doctrinal intention [XVI:543–544]","author":"tibi","on":["K099.07"],"anchor":"K099.07","surah":99,"ar":"وقلت: الآية تحتمل معنيين: أن يراد بإحدى القرينتين السعداء وبالأخرى الأشقياء لتكرير الموصول، وأن يراد العموم في كل قرينة كما يقال: فمن يعمل مثقال ذرة من المؤمنين والكافرين خيراً يره، ومن يعمل مثقال ذرة من المؤمنين والكافرين شراً يره. وعلى الأول ورد كلام المصنف، وما روى محيي السنة والإمام عن محمد بن كعب القرظي: فمن يعمل مثقال ذرة من خير وهو كافر، فإنه يرى ثواب ذلك في الدنيا في نفسه وأهله وماله، حتى يلقى الآخرة وليس له فيها خير.\n\nومن يعمل مثقال ذرة من شر وهو مؤمن، كُفر ذلك في الدنيا في نفسه وأهله وماله، حتى بلغ الآخرة وليس له فيها شر. لكن قصد المصنف في ذلك إدخال مرتكب الكبيرة في زمرة الكفار والأشقياء، لأن حسنات مرتكب الكبيرة محبطة به فلا يرى غير الشر، كما أن صغائر مجتنب الكبائر مكفرة به، فلا يرى غير الخير، يُعلم ذلك من سؤاله. وعلى الثاني ما رواه الواحدي عن مقاتل: فمن يعمل في الدنيا مثقال ذرة خيراً،\n\nيره يوم القيامة فيفرح به، وكذلك الشر فيراه في كتابه، فيسوؤه ذلك. وروى محيي السنة والإمام عن ابن عباس: ليس من مؤمن ولا كافر عمل خيراً كان أو شراً، إلا أراه الله تعالى إياه؛ فأما المؤمن فتغفر له سيئاته ويُثيبه بحسناته، وأما الكافر فتُرد حسناته ويعذب بسيئاته.","html":"<p>I say: the verse admits two meanings. One paired clause may intend the felicitous and the other the wretched, since the relative expression is repeated. Or each clause may intend generality: whoever among believers and unbelievers does an atom’s weight of good will see it, and whoever among believers and unbelievers does an atom’s weight of evil will see it.</p><p>The author’s words follow the first interpretation, as does what Muḥyī al-Sunna [al-Baghawī] and the Imām transmit from Muḥammad ibn Kaʿb al-Quraẓī: whoever does an atom’s weight of good while an unbeliever sees its reward in this world—in himself, his family, and his property—until he meets the hereafter with no good awaiting him there. Whoever does an atom’s weight of evil while a believer has it expiated in this world—in himself, his family, and his property—until he reaches the hereafter with no evil awaiting him there.</p><p>But the author’s intention is to include the person committing a major sin among the unbelievers and the wretched, because that person’s good deeds are nullified by it and he therefore sees only evil; just as the minor sins of one avoiding major sins are expiated through that avoidance and he sees only good. This is known from his question.</p><p>On the second interpretation comes what al-Wāḥidī transmits from Muqātil: whoever does an atom’s weight of good in this world will see it on the Day of Resurrection and rejoice in it. Likewise with evil: he sees it in his record, and it grieves him. Muḥyī al-Sunna and the Imām transmit from Ibn ʿAbbās: no believer or unbeliever does anything, good or evil, without God showing it to him. The believer’s evil deeds are forgiven and he is rewarded for his good deeds; the unbeliever’s good deeds are rejected and he is punished for his evil deeds.</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.10","heading":"T099.10 — Wording, meaning, and style favour generality [XVI:544–545]","text":"This latter possibility is supported by the wording, the meaning, and the style.\n\nAs for the wording: “Whoever does,” as already stated, elaborates the preceding “People will come forth separately, to be shown their deeds,” so the two must agree. “Their deeds” is a plural in a possessive construction and conveys comprehensiveness and inclusion of all. “People will come forth” is qualified by “separately,” indicating that they take diverse routes to settle in their stations in Paradise and the Fire according to their differing deeds. Hence Paradise has ascending degrees and the Fire descending levels.\n\nAs for the meaning: the passage explains the exhaustive display of deeds and their recompense, as in His saying, “We shall set up the just scales for the Day of Resurrection, and no soul will be wronged in anything. Even if it is the weight of a mustard seed, We shall bring it; and We suffice as reckoners” [21:47].\n\nAs for the style: this is one of the comprehensive statements containing the benefits of religion, both its foundations and its branches. We have transmitted from al-Bukhārī and Muslim, from Abū Hurayra, that God’s Messenger was asked about donkeys and said, “Nothing has been revealed to me concerning them except this comprehensive, unique verse,” and recited it. “About donkeys” means about alms on donkeys. Fādhdha, “unique,” means singular in its meaning: a man fadhdha from his companions when he separated from them.\n\nImām Aḥmad transmits from Ṣaʿṣaʿa ibn Muʿāwiya, al-Farazdaq’s uncle, that he came to the Prophet, who recited the verse. He said, “That is enough for me; I do not mind hearing nothing else.” In al-Ḥaqāʾiq: a sage was asked, “Admonish us,” and recited the verse. The questioner said, “Then the admonition has reached its utmost.”","title":"Wording, meaning, and style favour generality [XVI:544–545]","author":"tibi","on":["K099.07"],"anchor":"K099.07","surah":99,"ar":"وهذا الاحتمال يساعده النظم والمعنى والأسلوب.\n\nأما النظم، فإن قوله ﴿فَمَن يَعْمَلْ﴾ كما سبق، تفصيل لما عقب به من قوله ﴿يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ﴾، فيجب التوافق. والأعمال جمع مضاف يفيد الشمول والاستغراق، ﴿يَصْدُرُ النَّاسُ﴾ مقيد بقوله ﴿أَشْتَاتًا﴾، فيفيد أنهم على طرائق شتى للنزول في منازلهم من الجنة والنار، بحسب أعمالهم المختلفة، ومن ثم كانت الجنة ذات درجات، والنار ذات دركات.\n\nوأما المعنى، فإنها وردت لبيان الاستقصاء في عرض الأعمال والجزاء عليها، لقوله تعالى: ﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَى بِنَا حَاسِبِينَ﴾ [الأنبياء: 47].\n\nوأما الأسلوب، فإنها من الجوامع الحاوية لفوائد الدين أصولاً وفروعاً، روينا عن البخاري ومسلم عن أبي هريرة: سُئل رسول الله ﷺ عن الحمر، فقال: لم ينزل علي فيها شيء إلا هذه الآية الجامعة الفاذة، فتلاها.\n\nقوله: عن الحُمر، أي: عن صدقة الحُمر. والفاذة: أي المنفردة في معناها؛ فذ الرجل عن أصحابه إذا شذ عنهم. وروى الإمام أحمد عن صعصعة بن معاوية عم الفرزدق، أنه\n\nأتى النبي صلى الله عليه وسلم، فقرأ الآية، فقال: حسبي، لا أبالي أن لا أسمع غيرها. وفي \"الحقائق\": قيل لبعض الحكماء: عظ، فتلا الآية. فقال السائل: فقد انتهت الموعظة.","html":"<p>This latter possibility is supported by the wording, the meaning, and the style.</p><p>As for the wording: “Whoever does,” as already stated, elaborates the preceding “People will come forth separately, to be shown their deeds,” so the two must agree. “Their deeds” is a plural in a possessive construction and conveys comprehensiveness and inclusion of all. “People will come forth” is qualified by “separately,” indicating that they take diverse routes to settle in their stations in Paradise and the Fire according to their differing deeds. Hence Paradise has ascending degrees and the Fire descending levels.</p><p>As for the meaning: the passage explains the exhaustive display of deeds and their recompense, as in His saying, “We shall set up the just scales for the Day of Resurrection, and no soul will be wronged in anything. Even if it is the weight of a mustard seed, We shall bring it; and We suffice as reckoners” [21:47].</p><p>As for the style: this is one of the comprehensive statements containing the benefits of religion, both its foundations and its branches. We have transmitted from al-Bukhārī and Muslim, from Abū Hurayra, that God’s Messenger was asked about donkeys and said, “Nothing has been revealed to me concerning them except this comprehensive, unique verse,” and recited it. “About donkeys” means about alms on donkeys. Fādhdha, “unique,” means singular in its meaning: a man fadhdha from his companions when he separated from them.</p><p>Imām Aḥmad transmits from Ṣaʿṣaʿa ibn Muʿāwiya, al-Farazdaq’s uncle, that he came to the Prophet, who recited the verse. He said, “That is enough for me; I do not mind hearing nothing else.” In al-Ḥaqāʾiq: a sage was asked, “Admonish us,” and recited the verse. The questioner said, “Then the admonition has reached its utmost.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:7","number":7,"ar":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ","en":"And whoso doeth good an atom's weight will see it then"},{"key":"99:8","number":8,"ar":"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ","en":"And whoso doeth ill an atom's weight will see it then"}],"quran_ar":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ ﴿7﴾ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ ﴿8﴾","quran_en":"7. And whoso doeth good an atom's weight will see it then 8. And whoso doeth ill an atom's weight will see it then"},{"id":"K099.08","q":"99:1–8","s":99,"surah":"al-Zalzalah","surah_ar":"الزلزلة","title":"al-Zalzalah · Closing report","cairo":"K IV:783–785 · T XVI:536–545","source_page_first":783,"source_page_last":785,"chunk":"passages-099","segments":[{"type":"exposition","title":"Closing report [IV:785]","html":"<p>From God’s Messenger: “Whoever recites Sūrat ‘When the earth is shaken’ four times is like someone who recites the whole Qurʾān.”</p>","author":"kashshaf","source_id":"K099.08"},{"type":"exposition","title":"The closing report and another transmitted measure [XVI:545]","html":"<p>On “whoever recites Sūrat ‘When the earth is shaken’ four times”: we have transmitted from al-Tirmidhī, from Ibn ʿAbbās, who said that God’s Messenger said: “Whoever recites ‘When the earth is shaken,’ it is reckoned for him as half the Qurʾān.”</p><p>End of the sūrah.</p>","author":"tibi","source_id":"T099.11"}],"types":["exposition","language","theology","reports"],"ar":"عن رسول الله صلى الله عليه وسلم. «من قرأ سورة إذا زلزلت أربع مرات كان كمن قرأ القرآن كله» .\n\nقوله: (من قرأ [سورة] ﴿إِذَا زُلْزِلَتِ﴾ أربع مرات، روينا عن الترمذي، عن ابن عباس، قال: قال رسول الله ﷺ : \"من قرأ: ﴿إِذَا زُلْزِلَتِ﴾ عُدلت له بنصف القرآن\".\n\nتمت السورة","layers":[{"id":"K099.08","heading":"K099.08 — Closing report [IV:785]","text":"From God’s Messenger: “Whoever recites Sūrat ‘When the earth is shaken’ four times is like someone who recites the whole Qurʾān.”","title":"Closing report [IV:785]","author":"kashshaf","surah":99,"ar":"عن رسول الله صلى الله عليه وسلم. «من قرأ سورة إذا زلزلت أربع مرات كان كمن قرأ القرآن كله» .","html":"<p>From God’s Messenger: “Whoever recites Sūrat ‘When the earth is shaken’ four times is like someone who recites the whole Qurʾān.”</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}},{"id":"T099.11","heading":"T099.11 — The closing report and another transmitted measure [XVI:545]","text":"On “whoever recites Sūrat ‘When the earth is shaken’ four times”: we have transmitted from al-Tirmidhī, from Ibn ʿAbbās, who said that God’s Messenger said: “Whoever recites ‘When the earth is shaken,’ it is reckoned for him as half the Qurʾān.”\n\nEnd of the sūrah.","title":"The closing report and another transmitted measure [XVI:545]","author":"tibi","on":["K099.08"],"anchor":"K099.08","surah":99,"ar":"قوله: (من قرأ [سورة] ﴿إِذَا زُلْزِلَتِ﴾ أربع مرات، روينا عن الترمذي، عن ابن عباس، قال: قال رسول الله ﷺ : \"من قرأ: ﴿إِذَا زُلْزِلَتِ﴾ عُدلت له بنصف القرآن\".\n\nتمت السورة","html":"<p>On “whoever recites Sūrat ‘When the earth is shaken’ four times”: we have transmitted from al-Tirmidhī, from Ibn ʿAbbās, who said that God’s Messenger said: “Whoever recites ‘When the earth is shaken,’ it is reckoned for him as half the Qurʾān.”</p><p>End of the sūrah.</p>","lemma":"","review":{"electronic_comparison":"completed","new_scan_collation":false,"final_scholarly_approval":false,"dossier":"reviews/new-batch.json","arabic_complete":true}}],"cairo_notes":[],"verses":[{"key":"99:1","number":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","en":"When Earth is shaken with her (final) earthquake"},{"key":"99:2","number":2,"ar":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","en":"And Earth yieldeth up her burdens"},{"key":"99:3","number":3,"ar":"وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا","en":"And man saith: What aileth her"},{"key":"99:4","number":4,"ar":"يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا","en":"That day she will relate her chronicles"},{"key":"99:5","number":5,"ar":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","en":"Because thy Lord inspireth her"},{"key":"99:6","number":6,"ar":"يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ","en":"That day mankind will issue forth in scattered groups to be shown their deeds"},{"key":"99:7","number":7,"ar":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ","en":"And whoso doeth good an atom's weight will see it then"},{"key":"99:8","number":8,"ar":"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ","en":"And whoso doeth ill an atom's weight will see it then"}],"quran_ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا ﴿1﴾ وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا ﴿2﴾ وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا ﴿3﴾ يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿4﴾ بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا ﴿5﴾ يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ ﴿6﴾ فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ ﴿7﴾ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ ﴿8﴾","quran_en":"1. When Earth is shaken with her (final) earthquake 2. And Earth yieldeth up her burdens 3. And man saith: What aileth her 4. That day she will relate her chronicles 5. Because thy Lord inspireth her 6. That day mankind will issue forth in scattered groups to be shown their deeds 7. And whoso doeth good an atom's weight will see it then 8. And whoso doeth ill an atom's weight will see it then"}];
